TRUNCATE TABLE public.questions RESTART IDENTITY;

INSERT INTO public.questions (chapter, question_text, options, correct_answer) VALUES
-- ==========================================
-- BAB 1: Kepramukaan Dasar
-- ==========================================
(1, 'Siapakah penulis buku referensi Pramuka "Boyman"?', '["A. Soenardjo Atmodipuro","B. Mayor Kenneth McLaren","C. Andri Bob Sunardi","D. Lord Edward Cecil"]', 'C. Andri Bob Sunardi'),
(1, 'Sifat kepramukaan yang penyelenggaraannya disesuaikan dengan keadaan dan kebutuhan masyarakat di negaranya adalah sifat...', '["A. Kenya","B. Nasional","C. Mafeking","D. Pulau Brownsea"]', 'B. Nasional'),
(1, 'Kepramukaan dapat berlaku untuk siapa saja dan diselenggarakan di mana saja. Ini disebut sifat...', '["A. Universal","B. Andri Bob Sunardi","C. H. Mutahar","D. Ki Hajar Dewantara"]', 'A. Universal'),
(1, 'Kepramukaan harus dapat mengembangkan rasa persaudaraan dan persahabatan antar sesama manusia. Ini adalah cerminan dari sifat...', '["A. 7 - 10 tahun","B. Internasional","C. 21 - 25 tahun","D. 14 - 18 tahun"]', 'B. Internasional'),
(1, 'Fungsi kepramukaan bagi peserta didik (anak/pemuda) pada dasarnya adalah sebagai...', '["A. Sri Sultan Hamengkubuwono IX","B. Ambalan","C. Permainan yang menarik","D. Perindukan"]', 'C. Permainan yang menarik'),
(1, 'Bagi orang dewasa, kepramukaan bukan lagi permainan, melainkan suatu tugas yang memerlukan keikhlasan. Ini adalah fungsi sebagai...', '["A. Disentri","B. Pengabdian","C. Patah Tulang","D. Pingsan"]', 'B. Pengabdian'),
(1, 'Kepramukaan berfungsi sebagai alat untuk memenuhi kebutuhan dan tujuan masyarakat. Ini adalah fungsi kepramukaan bagi...', '["A. Tenda Prisma","B. Survival Kit","C. Flysheet","D. Masyarakat dan Organisasi"]', 'D. Masyarakat dan Organisasi'),
(1, 'Proses pendidikan di luar lingkungan sekolah dan keluarga dalam bentuk kegiatan menarik di alam terbuka disebut...', '["A. Soenardjo Atmodipuro","B. Kepramukaan","C. Bunga Lily (Fleur-de-lis)","D. Pramuka"]', 'B. Kepramukaan'),
(1, 'Orang-orang atau anggota yang mengikuti kegiatan dan tergabung di dalam organisasi kepanduan di Indonesia disebut...', '["A. Pramuka","B. Purwa, Madya, Utama","C. Pasukan","D. Trisatya dan Dasadarma"]', 'A. Pramuka'),
(1, 'Organisasi atau wadah resmi yang menyelenggarakan pendidikan kepramukaan di Indonesia adalah...', '["A. Perindukan","B. Racana","C. Gerakan Pramuka","D. Pasukan"]', 'C. Gerakan Pramuka'),
(1, 'Kepanjangan dari PRAMUKA adalah...', '["A. Praja Muda Karana","B. Ing Madyo Mangun Karso","C. Nasional","D. Bunga Lily (Fleur-de-lis)"]', 'A. Praja Muda Karana'),
(1, 'Istilah Praja Muda Karana memiliki arti...', '["A. Tulisan","B. Rakyat muda yang suka berkarya","C. Sandi","D. Pesan"]', 'B. Rakyat muda yang suka berkarya'),
(1, 'Bapak Pramuka Indonesia adalah...', '["A. Olave St. Clair Soames","B. Soenardjo Atmodipuro","C. Sri Sultan Hamengkubuwono IX","D. Lord Robert Baden Powell"]', 'C. Sri Sultan Hamengkubuwono IX'),
(1, 'Bapak Pandu Dunia (Chief Scout of the World) adalah...', '["A. Lord Robert Baden Powell","B. W.R. Supratman","C. H. Mutahar","D. Soenardjo Atmodipuro"]', 'A. Lord Robert Baden Powell'),
(1, 'Tujuan Gerakan Pramuka yang pertama adalah membentuk anggota pramuka agar memiliki kepribadian yang...', '["A. Purwa, Madya, Utama","B. Dwisatya dan Dwidarma","C. Beriman, bertakwa, dan berakhlak mulia","D. Andri Bob Sunardi"]', 'C. Beriman, bertakwa, dan berakhlak mulia'),
(1, 'Tujuan Gerakan Pramuka yang kedua adalah agar anggota pramuka menjadi warga negara yang...', '["A. Gilwell Park","B. Berjiwa Pancasila","C. Nyeri","D. Olympia Hall"]', 'B. Berjiwa Pancasila'),
(1, 'Salah satu pilar metode kepramukaan adalah "Learning by Doing", yang artinya...', '["A. Keberanian","B. Belajar sambil melakukan","C. Tulisan","D. Kesucian"]', 'B. Belajar sambil melakukan'),
(1, 'Penggolongan usia Pramuka Siaga adalah...', '["A. 7 - 10 tahun","B. 17 - 25 tahun","C. 16 - 20 tahun","D. 14 - 18 tahun"]', 'A. 7 - 10 tahun'),
(1, 'Penggolongan usia Pramuka Penggalang adalah...', '["A. 21 - 25 tahun","B. 11 - 15 tahun","C. 16 - 20 tahun","D. 7 - 10 tahun"]', 'B. 11 - 15 tahun'),
(1, 'Penggolongan usia Pramuka Penegak adalah...', '["A. 14 - 18 tahun","B. 17 - 25 tahun","C. 16 - 20 tahun","D. 21 - 25 tahun"]', 'C. 16 - 20 tahun'),
(1, 'Penggolongan usia Pramuka Pandega adalah...', '["A. 17 - 25 tahun","B. 16 - 20 tahun","C. 7 - 10 tahun","D. 21 - 25 tahun"]', 'D. 21 - 25 tahun'),
(1, 'Kode Kehormatan bagi Pramuka Siaga terdiri dari...', '["A. Trisatya dan Dasadarma","B. Dwisatya dan Dwidarma","C. Satyaku Kudarmakan, Darmaku Kubaktikan","D. Ing Ngarso Sung Tulodo"]', 'B. Dwisatya dan Dwidarma'),
(1, 'Kode Kehormatan bagi Pramuka Penggalang, Penegak, dan Pandega terdiri dari...', '["A. Ikhlas Bakti Bina Bangsa","B. Trisatya dan Dasadarma","C. Be Prepared (Selalu Siap)","D. Satyaku Kudarmakan, Darmaku Kubaktikan"]', 'B. Trisatya dan Dasadarma'),
(1, 'Sistem Pendidikan Kepramukaan menggunakan Sistem Among yang digagas oleh...', '["A. Purwa, Madya, Utama","B. 11 - 15 tahun","C. Ki Hajar Dewantara","D. Pasukan"]', 'C. Ki Hajar Dewantara'),
(1, 'Semboyan Sistem Among di depan memberikan teladan adalah...', '["A. Ing Ngarso Sung Tulodo","B. Trisatya dan Dasadarma","C. Ing Madyo Mangun Karso","D. Tut Wuri Handayani"]', 'A. Ing Ngarso Sung Tulodo'),
(1, 'Semboyan Sistem Among di tengah membangun kemauan adalah...', '["A. Satyaku Kudarmakan, Darmaku Kubaktikan","B. Ing Madyo Mangun Karso","C. Ing Ngarso Sung Tulodo","D. Be Prepared (Selalu Siap)"]', 'B. Ing Madyo Mangun Karso'),
(1, 'Semboyan Sistem Among di belakang memberikan dorongan adalah...', '["A. Be Prepared (Selalu Siap)","B. Ing Madyo Mangun Karso","C. Tut Wuri Handayani","D. Dwisatya dan Dwidarma"]', 'C. Tut Wuri Handayani'),
(1, 'Satuan terkecil dalam Pramuka Siaga disebut...', '["A. Gugus Depan","B. Perindukan","C. Barung","D. Racana"]', 'C. Barung'),
(1, 'Satuan terkecil dalam Pramuka Penggalang disebut...', '["A. Racana","B. Regu","C. Barung","D. Ambalan"]', 'B. Regu'),
(1, 'Satuan terkecil dalam Pramuka Penegak disebut...', '["A. Ambalan","B. Kwartir","C. Regu","D. Sangga"]', 'D. Sangga'),
(1, 'Satuan terkecil dalam Pramuka Pandega disebut...', '["A. Reka","B. Regu","C. Barung","D. Kwartir"]', 'A. Reka'),
(1, 'Kumpulan dari beberapa Barung dalam Siaga disebut...', '["A. Gugus Depan","B. Perindukan","C. Racana","D. Kwartir"]', 'B. Perindukan'),
(1, 'Kumpulan dari beberapa Regu dalam Penggalang disebut...', '["A. Racana","B. Pasukan","C. Ambalan","D. Barung"]', 'B. Pasukan'),
(1, 'Kumpulan dari beberapa Sangga dalam Penegak disebut...', '["A. Ambalan","B. Kwartir","C. Perindukan","D. Regu"]', 'A. Ambalan'),
(1, 'Wadah pembinaan Pramuka Pandega di Perguruan Tinggi disebut...', '["A. Ambalan","B. Racana","C. Reka","D. Perindukan"]', 'B. Racana'),
(1, 'Tanda kecakapan dalam kepramukaan dibagi menjadi dua, yaitu...', '["A. TKU dan TKK","B. Nasional","C. Satyaku Kudarmakan, Darmaku Kubaktikan","D. Lord Robert Baden Powell"]', 'A. TKU dan TKK'),
(1, 'TKU singkatan dari...', '["A. Siaga, Penggalang, Penegak","B. Tanda Kecakapan Umum","C. Ramu, Rakit, Terap","D. Mula, Bantu, Tata"]', 'B. Tanda Kecakapan Umum'),
(1, 'TKK singkatan dari...', '["A. Tanda Kecakapan Khusus","B. Siaga, Penggalang, Penegak","C. Purwa, Madya, Utama","D. Pramuka Garuda"]', 'A. Tanda Kecakapan Khusus'),
(1, 'Tingkatan TKU pada Pramuka Siaga adalah...', '["A. Ramu, Rakit, Terap","B. Mula, Bantu, Tata","C. Purwa, Madya, Utama","D. Bantara, Laksana"]', 'B. Mula, Bantu, Tata'),
(1, 'Tingkatan TKU pada Pramuka Penggalang adalah...', '["A. Ramu, Rakit, Terap","B. Bantara, Laksana","C. Pramuka Garuda","D. Purwa, Madya, Utama"]', 'A. Ramu, Rakit, Terap'),
(1, 'Tingkatan TKU pada Pramuka Penegak adalah...', '["A. Bantara, Laksana","B. Siaga, Penggalang, Penegak","C. Ramu, Rakit, Terap","D. Purwa, Madya, Utama"]', 'A. Bantara, Laksana'),
(1, 'Tingkatan TKK (Tanda Kecakapan Khusus) dibagi menjadi 3 tingkatan, yaitu...', '["A. Ramu, Rakit, Terap","B. Mula, Bantu, Tata","C. Purwa, Madya, Utama","D. Siaga, Penggalang, Penegak"]', 'C. Purwa, Madya, Utama'),
(1, 'Lambang Gerakan Pramuka Indonesia adalah...', '["A. Tunas Kelapa","B. Nasional","C. Pramuka Garuda","D. Praja Muda Karana"]', 'A. Tunas Kelapa'),
(1, 'Pencipta lambang Tunas Kelapa adalah...', '["A. Andri Bob Sunardi","B. Soenardjo Atmodipuro","C. Olave St. Clair Soames","D. Agnes Baden-Powell"]', 'B. Soenardjo Atmodipuro'),
(1, 'Bentuk lambang Pramuka Internasional (WOSM) adalah...', '["A. Masyarakat dan Organisasi","B. Praja Muda Karana","C. Bunga Lily (Fleur-de-lis)","D. 14 Agustus"]', 'C. Bunga Lily (Fleur-de-lis)'),
(1, 'Gerakan Pramuka resmi diperkenalkan kepada rakyat Indonesia pada tanggal...', '["A. 14 Agustus 1961","B. 14 Agustus 1962","C. 14 Agustus 1960","D. 14 Agustus 1962"]', 'A. 14 Agustus 1961'),
(1, 'Oleh karena itu, Hari Pramuka di Indonesia diperingati setiap tanggal...', '["A. 14 Agustus","B. 12 Agustus","C. 16 Agustus","D. 19 Agustus"]', 'A. 14 Agustus'),
(1, 'Undang-Undang yang mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. Lord Robert Baden Powell","B. UU No. 12 Tahun 2010","C. 21 - 25 tahun","D. 7 - 10 tahun"]', 'B. UU No. 12 Tahun 2010'),
(1, 'Motto Gerakan Pramuka adalah...', '["A. Satyaku Kudarmakan, Darmaku Kubaktikan","B. Be Prepared (Selalu Siap)","C. Dwisatya dan Dwidarma","D. Ikhlas Bakti Bina Bangsa"]', 'A. Satyaku Kudarmakan, Darmaku Kubaktikan'),
(1, 'Tingkatan tertinggi dalam setiap golongan Pramuka yang telah memenuhi syarat pencapaian Garuda disebut...', '["A. Mula, Bantu, Tata","B. Purwa, Madya, Utama","C. Pramuka Garuda","D. Ramu, Rakit, Terap"]', 'C. Pramuka Garuda'),

-- ==========================================
-- BAB 3: Biografi Baden Powell
-- ==========================================
(3, 'Nama lengkap Bapak Pandu Dunia adalah...', '["A. Robert Stephenson Smyth Baden-Powell","B. H. Mutahar","C. Soenardjo Atmodipuro","D. Samuel F.B. Morse"]', 'A. Robert Stephenson Smyth Baden-Powell'),
(3, 'Baden-Powell lahir di kota...', '["A. Olympia Hall","B. Pulau Brownsea","C. London","D. Kenya"]', 'C. London'),
(3, 'Tanggal lahir Baden-Powell adalah...', '["A. 24 Februari 1857","B. 22 Februari 1857","C. 22 Februari 1856","D. 24 Februari 1857"]', 'B. 22 Februari 1857'),
(3, 'Nama ayah Baden-Powell adalah...', '["A. Prof. Domine Baden-Powell","B. Olave St. Clair Soames","C. Mayor Kenneth McLaren","D. Ki Hajar Dewantara"]', 'A. Prof. Domine Baden-Powell'),
(3, 'Profesi ayah Baden-Powell adalah seorang...', '["A. Serigala yang tidak pernah tidur","B. Guru Besar Geometri di Universitas Oxford","C. Miss Henrietta Grace Smyth","D. Admiral William T. Smyth"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(3, 'Nama ibu dari Baden-Powell adalah...', '["A. Agnes Baden-Powell","B. Lord Edward Cecil","C. Miss Henrietta Grace Smyth","D. W.R. Supratman"]', 'C. Miss Henrietta Grace Smyth'),
(3, 'Ayah dari ibu Baden-Powell (kakek dari pihak ibu) adalah seorang laksamana bernama...', '["A. Admiral William T. Smyth","B. W.R. Supratman","C. Rudyard Kipling","D. Ki Hajar Dewantara"]', 'A. Admiral William T. Smyth'),
(3, 'Ayah Baden-Powell meninggal dunia ketika Baden-Powell berusia...', '["A. 3 tahun","B. 8 tahun","C. 1 tahun","D. 1 tahun"]', 'A. 3 tahun'),
(3, 'Julukan Baden-Powell saat bersekolah di Charterhouse School karena kebiasaannya mandi air dingin adalah...', '["A. Hipotermia","B. Bathing Towel","C. Diare","D. Pingsan"]', 'B. Bathing Towel'),
(3, 'Kepala sekolah di Charterhouse yang sangat berpengaruh terhadap pembentukan karakter Baden-Powell adalah...', '["A. Dr. Haig Brown","B. 1918","C. Robert Stephenson Smyth Baden-Powell","D. Rovering to Success"]', 'A. Dr. Haig Brown'),
(3, 'Setelah lulus dari Charterhouse, Baden-Powell mengikuti ujian militer dan lulus kavaleri dengan urutan ke...', '["A. Gilwell Park","B. Dua","C. The Jungle Book","D. Prof. Domine Baden-Powell"]', 'B. Dua'),
(3, 'Pasukan kavaleri yang pertama kali ditempati Baden-Powell di India adalah...', '["A. Olympia Hall","B. London","C. 13th Hussars","D. Mafeking"]', 'C. 13th Hussars'),
(3, 'Baden-Powell pertama kali ditugaskan ke India sebagai prajurit muda pada tahun...', '["A. 1876","B. 1871","C. 1873","D. 1878"]', 'A. 1876'),
(3, 'Pangkat pertama Baden-Powell saat bergabung di ketentaraan di India adalah...', '["A. 22 anak","B. 22 Februari 1857","C. Pembantu Letnan (Sub-Lieutenant)","D. Saya telah pulang"]', 'C. Pembantu Letnan (Sub-Lieutenant)'),
(3, 'Suku Zulu, Ashanti, dan Matabele di Afrika memberikan julukan khusus kepada Baden-Powell, yaitu...', '["A. Patah Tulang","B. Impeesa","C. Hipotermia","D. Luka Bakar"]', 'B. Impeesa'),
(3, 'Arti dari julukan "Impeesa" yang diberikan oleh suku di Afrika adalah...', '["A. Demam Berdarah","B. Disentri","C. Serigala yang tidak pernah tidur","D. Diare"]', 'C. Serigala yang tidak pernah tidur'),
(3, 'Baden-Powell berhasil mempertahankan sebuah kota dari kepungan bangsa Boer di Afrika Selatan selama 217 hari. Kota tersebut bernama...', '["A. Timur","B. Barat Laut","C. Timur Laut","D. Mafeking"]', 'D. Mafeking'),
(3, 'Peristiwa pengepungan kota Mafeking terjadi pada tahun...', '["A. Gilwell Park","B. 1899 - 1900","C. Pulau Brownsea","D. Nyeri"]', 'B. 1899 - 1900'),
(3, 'Buku panduan pelacakan militer yang ditulis Baden-Powell dan kelak disukai oleh anak-anak muda Inggris adalah...', '["A. Scouting for Boys","B. Aids to Scouting","C. Boyman","D. Rovering to Success"]', 'B. Aids to Scouting'),
(3, 'Buku "Aids to Scouting" diterbitkan pada tahun...', '["A. 1899","B. 1903","C. 1895","D. 1897"]', 'A. 1899'),
(3, 'Perkemahan percobaan kepanduan pertama kali diadakan oleh Baden-Powell di sebuah pulau bernama...', '["A. H. Mutahar","B. Pulau Brownsea","C. Agnes Baden-Powell","D. Samuel F.B. Morse"]', 'B. Pulau Brownsea'),
(3, 'Perkemahan di Pulau Brownsea yang menjadi tonggak sejarah kepramukaan dilaksanakan pada tahun...', '["A. 1908","B. 1907","C. 1910","D. 1904"]', 'B. 1907'),
(3, 'Berapa jumlah anak laki-laki yang mengikuti perkemahan percobaan di Pulau Brownsea?', '["A. 26 anak","B. 23 anak","C. 22 anak","D. 26 anak"]', 'C. 22 anak'),
(3, 'Teman tentara yang membantu Baden-Powell mengurus perkemahan di Pulau Brownsea adalah...', '["A. Mayor Kenneth McLaren","B. Nyeri","C. Kenya","D. Pulau Brownsea"]', 'A. Mayor Kenneth McLaren'),
(3, 'Buku panduan utama yang menjadi cikal bakal berdirinya gerakan kepanduan dunia adalah...', '["A. Aids to Scouting","B. The Jungle Book","C. Scouting for Boys","D. Rovering to Success"]', 'C. Scouting for Boys'),
(3, 'Buku "Scouting for Boys" karya Baden-Powell pertama kali diterbitkan pada tahun...', '["A. 1904","B. 1908","C. 1913","D. 1905"]', 'B. 1908'),
(3, 'Organisasi kepanduan putri (Girl Guides) pertama kali dibentuk dengan bantuan adik perempuan Baden-Powell yang bernama...', '["A. Sri Sultan Hamengkubuwono IX","B. Rudyard Kipling","C. Agnes Baden-Powell","D. Samuel F.B. Morse"]', 'C. Agnes Baden-Powell'),
(3, 'Organisasi Girl Guides (Kepanduan Putri) dirintis pada tahun...', '["A. 1911","B. 1910","C. 1908","D. 1915"]', 'B. 1910'),
(3, 'Kepanduan untuk golongan anak-anak (Siaga/Wolf Cub) didirikan oleh Baden-Powell pada tahun...', '["A. 1917","B. 1921","C. 1916","D. 1915"]', 'C. 1916'),
(3, 'Buku panduan yang digunakan Baden-Powell untuk menginspirasi golongan Siaga (Wolf Cub) adalah...', '["A. Scouting for Boys","B. The Jungle Book","C. Rovering to Success","D. Aids to Scouting"]', 'B. The Jungle Book'),
(3, 'Penulis buku "The Jungle Book" yang menginspirasi pembentukan golongan Siaga adalah...', '["A. Rudyard Kipling","B. Boyman","C. Aids to Scouting","D. Scouting for Boys"]', 'A. Rudyard Kipling'),
(3, 'Kepanduan untuk golongan pemuda (Penegak/Rover Scout) dibentuk pada tahun...', '["A. 1917","B. 1918","C. 1920","D. 1921"]', 'B. 1918'),
(3, 'Buku panduan untuk Rover Scout yang ditulis oleh Baden-Powell pada tahun 1922 berjudul...', '["A. Scouting for Boys","B. Aids to Scouting","C. Rovering to Success","D. Boyman"]', 'C. Rovering to Success'),
(3, 'Jambore Kepanduan Dunia pertama kali diadakan di gedung...', '["A. Olympia Hall","B. Admiral William T. Smyth","C. London","D. 1919"]', 'A. Olympia Hall'),
(3, 'Jambore Dunia pertama diadakan di kota London pada tahun...', '["A. 1917","B. 1920","C. 1916","D. 1917"]', 'B. 1920'),
(3, 'Pada malam terakhir Jambore Dunia pertama, Baden-Powell secara resmi diangkat menjadi...', '["A. Guru Besar Geometri di Universitas Oxford","B. World Organization of the Scout Movement","C. Bapak Pandu Dunia (Chief Scout of the World)","D. Aids to Scouting"]', 'C. Bapak Pandu Dunia (Chief Scout of the World)'),
(3, 'Gelar kehormatan "Lord" (Baron) dianugerahkan kepada Baden-Powell oleh Raja George V pada tahun...', '["A. 1933","B. 1928","C. 1929","D. 1932"]', 'C. 1929'),
(3, 'Nama istri Baden-Powell yang kelak menjadi Chief Guide of the World adalah...', '["A. Mayor Kenneth McLaren","B. Olave St. Clair Soames","C. Agnes Baden-Powell","D. Sri Sultan Hamengkubuwono IX"]', 'B. Olave St. Clair Soames'),
(3, 'Baden-Powell pensiun dari dinas kemiliteran Inggris dengan pangkat terakhir...', '["A. 3 tahun","B. Letnan Jenderal","C. 1876","D. 22 anak"]', 'B. Letnan Jenderal'),
(3, 'Raja Inggris yang menyarankan Baden-Powell untuk pensiun dari militer agar bisa membesarkan Gerakan Kepanduan adalah...', '["A. 1899","B. 1908","C. Raja Edward VII","D. Mayor Kenneth McLaren"]', 'C. Raja Edward VII'),
(3, 'Pada tahun 1919, W. de Bois Maclaren menyumbangkan sebidang tanah untuk pusat pelatihan pembina pramuka yang diberi nama...', '["A. Andri Bob Sunardi","B. W.R. Supratman","C. Gilwell Park","D. Ki Hajar Dewantara"]', 'C. Gilwell Park'),
(3, 'Kursus Pembina Pramuka (Wood Badge) pertama kali diselenggarakan di Gilwell Park pada tahun...', '["A. 1921","B. 1919","C. 1920","D. 1918"]', 'B. 1919'),
(3, 'Kalung manik-manik kayu (Wood Badge) berasal dari kalung pimpinan suku Afrika yang pernah dikalahkan oleh Baden-Powell, bernama...', '["A. Lord Robert Baden Powell","B. Dinizulu","C. Andri Bob Sunardi","D. H. Mutahar"]', 'B. Dinizulu'),
(3, 'Simbol dari pusat pelatihan pembina Gilwell Park adalah...', '["A. Dr. Haig Brown","B. Miss Henrietta Grace Smyth","C. Kapak menancap di balok kayu","D. Admiral William T. Smyth"]', 'C. Kapak menancap di balok kayu'),
(3, 'Baden-Powell menghabiskan masa tuanya dan meninggal dunia di negara...', '["A. Gilwell Park","B. Pulau Brownsea","C. Afrika Selatan","D. Kenya"]', 'D. Kenya'),
(3, 'Baden-Powell meninggal dunia pada tanggal...', '["A. 8 Januari 1941","B. 8 Juli 1941","C. 8 Agustus 1941","D. 10 Januari 1941"]', 'A. 8 Januari 1941'),
(3, 'Baden-Powell dimakamkan di pemakaman St. Peter, di kota...', '["A. Afrika Selatan","B. London","C. Nyeri","D. Gilwell Park"]', 'C. Nyeri'),
(3, 'Usia Baden-Powell saat meninggal dunia adalah...', '["A. 86 tahun","B. 86 tahun","C. 83 tahun","D. 81 tahun"]', 'C. 83 tahun'),
(3, 'Pada batu nisan makam Baden-Powell terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti...', '["A. Saya telah pulang","B. Pesan","C. Kejayaan","D. Isyarat"]', 'A. Saya telah pulang'),
(3, 'Organisasi kepanduan dunia saat ini bernaung di bawah organisasi bernama WOSM, singkatan dari...', '["A. Ki Hajar Dewantara","B. World Organization of the Scout Movement","C. Sri Sultan Hamengkubuwono IX","D. Olave St. Clair Soames"]', 'B. World Organization of the Scout Movement'),

-- ==========================================
-- BAB 5: Scouting for Boys
-- ==========================================
(5, 'Bab 5 dalam buku referensi Boyman secara khusus membahas rangkuman dari buku legendaris karya Baden-Powell yang berjudul...', '["A. The Jungle Book","B. Scouting for Boys","C. Rovering to Success","D. Aids to Scouting"]', 'B. Scouting for Boys'),
(5, 'Buku Scouting for Boys pada dasarnya dibagi ke dalam beberapa sub-bab yang disebut dengan istilah...', '["A. The Jungle Book","B. Rovering to Success","C. Cerita Api Unggun","D. Scouting for Boys"]', 'C. Cerita Api Unggun'),
(5, 'Ada berapa total Cerita Api Unggun (Campfire Yarns) yang menjadi susunan utama materi Scouting for Boys?', '["A. 31 Cerita","B. 23 Cerita","C. 30 Cerita","D. 26 Cerita"]', 'D. 26 Cerita'),
(5, 'Cerita Api Unggun ke-1 membahas sejarah tentang pasukan anak laki-laki di Afrika yang menjadi inspirasi kepanduan, yang disebut...', '["A. Mafeking Cadet Corps","B. Barat Laut","C. Barat","D. Selatan"]', 'A. Mafeking Cadet Corps'),
(5, 'Pemimpin pasukan anak-anak pada masa pengepungan Mafeking tersebut adalah...', '["A. Raja Arthur","B. Lord Edward Cecil","C. Masakan di Perkemahan (Camp Cooking)","D. Good Turn (Berbuat Kebaikan)"]', 'B. Lord Edward Cecil'),
(5, 'Baden-Powell menyadari kehebatan pasukan anak-anak di Mafeking yang kemudian menjadi cikal bakal pentingnya peran kaum muda. Pengepungan kota Mafeking terjadi di negara...', '["A. Afrika Selatan","B. London","C. Pulau Brownsea","D. Kenya"]', 'A. Afrika Selatan'),
(5, 'Cerita Api Unggun ke-4 membahas inti dari sistem kepramukaan yang membagi anggota ke dalam kelompok kecil, disebut dengan...', '["A. Sherlock Holmes","B. Pionering / Kepeloporan","C. Sistem Regu (Patrol System)","D. Menolong orang lain di setiap kesempatan"]', 'C. Sistem Regu (Patrol System)'),
(5, 'Menurut gagasan awal Baden-Powell, jumlah anggota yang ideal dalam satu regu pramuka (patrol) adalah...', '["A. Jalan ke arah kanan","B. 6 sampai 8 orang","C. Masakan di Perkemahan (Camp Cooking)","D. 6 Latihan Fisik BP (BP Exercises)"]', 'B. 6 sampai 8 orang'),
(5, 'Sebutan untuk pemimpin regu dalam bahasa Inggris yang dicetuskan oleh Baden-Powell adalah...', '["A. Be Prepared (Selalu Siap)","B. Binatang dan Tumbuh-tumbuhan","C. Mafeking Cadet Corps","D. Patrol Leader"]', 'D. Patrol Leader'),
(5, 'Cerita Api Unggun ke-8 membahas tentang keterampilan membuat bangunan darurat menggunakan kayu dan tali, yang dalam istilah kepramukaan disebut...', '["A. Pionering / Kepeloporan","B. Diare","C. Hipotermia","D. Patah Tulang"]', 'A. Pionering / Kepeloporan'),
(5, 'Simpul dasar dalam pionering yang berguna untuk menyambung dua utas tali yang sama besar dan tidak licin adalah...', '["A. Simpul Mati (Reef Knot)","B. Simpul Tiang (Bowline)","C. Simpul Tali Tenda (Taut-line Hitch)","D. Simpul Anyam (Sheet Bend)"]', 'A. Simpul Mati (Reef Knot)'),
(5, 'Simpul yang berguna untuk mengikat leher binatang agar tidak tercekik, serta sering menjadi simpul dasar penyelamatan adalah...', '["A. Ikatan Silang","B. Ikatan Palang (Square Lashing)","C. Simpul Tiang (Bowline)","D. Simpul Anyam (Sheet Bend)"]', 'C. Simpul Tiang (Bowline)'),
(5, 'Simpul yang paling sering digunakan untuk memulai dan mengakhiri sebuah ikatan pada tongkat pionering adalah...', '["A. Simpul Delapan","B. Simpul Pangkal (Clove Hitch)","C. Simpul Anyam (Sheet Bend)","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'B. Simpul Pangkal (Clove Hitch)'),
(5, 'Simpul yang digunakan untuk menyambung dua utas tali yang ukurannya tidak sama besar dan dalam keadaan kering adalah...', '["A. Simpul Tiang (Bowline)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Ikatan Silang","D. Simpul Anyam (Sheet Bend)"]', 'D. Simpul Anyam (Sheet Bend)'),
(5, 'Ikatan yang digunakan untuk menggabungkan dua buah tongkat yang bersilangan tegak lurus (membentuk sudut 90 derajat) adalah...', '["A. Ikatan Palang (Square Lashing)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Ikatan Silang","D. Simpul Pangkal (Clove Hitch)"]', 'A. Ikatan Palang (Square Lashing)'),
(5, 'Cerita Api Unggun ke-9 membahas mengenai kehidupan di alam terbuka, yaitu rutinitas...', '["A. Simpul Tiang (Bowline)","B. Perkemahan (Camping)","C. Disiplin","D. Mafeking Cadet Corps"]', 'B. Perkemahan (Camping)'),
(5, 'Hal yang paling utama dan penting untuk diperhatikan saat memilih lokasi untuk mendirikan tenda perkemahan adalah...', '["A. Groundsheet / Terpal","B. Survival Kit","C. Dekat sumber air bersih dan aman dari bahaya alam","D. Sleeping Bag (Kantong Tidur)"]', 'C. Dekat sumber air bersih dan aman dari bahaya alam'),
(5, 'Cerita Api Unggun ke-10 memberikan panduan teknis yang sangat dibutuhkan regu mandiri, yaitu tentang...', '["A. Masakan di Perkemahan (Camp Cooking)","B. Binatang dan Tumbuh-tumbuhan","C. Santo George (St. George)","D. Tetap tenang dan tidak panik"]', 'A. Masakan di Perkemahan (Camp Cooking)'),
(5, 'Salah satu makanan khas perkemahan ala Baden-Powell, di mana adonan tepung dililitkan pada sebatang kayu lalu dipanggang di atas bara api, disebut...', '["A. Mafeking Cadet Corps","B. Roti Lilit (Twist)","C. Simpul Mati (Reef Knot)","D. Good Turn (Berbuat Kebaikan)"]', 'B. Roti Lilit (Twist)'),
(5, 'Cerita Api Unggun ke-11 dan 12 mengajarkan keterampilan mengasah kepekaan mata di alam terbuka, berupa...', '["A. Hidung, bukan mulut","B. Be Prepared (Selalu Siap)","C. Mencari dan Mengikuti Jejak (Tracking)","D. Simpul Pangkal (Clove Hitch)"]', 'C. Mencari dan Mengikuti Jejak (Tracking)'),
(5, 'Saat sedang mengikuti jejak di alam bebas, seorang Pramuka dianjurkan untuk berjalan dengan cara...', '["A. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","B. Masakan di Perkemahan (Camp Cooking)","C. Kesehatan fisik dan kebugaran tubuh","D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya"]', 'D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya'),
(5, 'Dalam sandi jejak Pramuka, susunan batu yang ditumpuk menjadi tiga bagian dan ditambahkan satu batu kecil di sebelah kanan memiliki arti...', '["A. Jalan ke arah kanan","B. Rahasia","C. Kesucian","D. Tulisan"]', 'A. Jalan ke arah kanan'),
(5, 'Sebuah lingkaran yang digambar di tanah dengan titik di tengahnya merupakan tanda jejak kepanduan yang berarti...', '["A. Isyarat","B. Kesucian","C. Saya telah pulang / Kembali ke perkemahan","D. Pesan"]', 'C. Saya telah pulang / Kembali ke perkemahan'),
(5, 'Cerita Api Unggun ke-13 menuntut seorang pandu untuk memiliki kemampuan observasi dan deduksi. Tokoh detektif fiksi yang sering dijadikan contoh oleh Baden-Powell untuk hal ini adalah...', '["A. Andri Bob Sunardi","B. Sherlock Holmes","C. Agnes Baden-Powell","D. Sri Sultan Hamengkubuwono IX"]', 'B. Sherlock Holmes'),
(5, 'Cerita Api Unggun ke-14 berjudul "Menyembunyikan Diri - Mengendap" (Stalking). Mengendap sangat berguna di alam bebas untuk...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","C. Melakukan tekanan langsung pada area luka / balut tekan","D. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh"]', 'A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut'),
(5, 'Aturan utama yang harus diperhatikan seorang Pramuka saat sedang mengendap mendekati target di alam liar adalah...', '["A. Simpul Pangkal (Clove Hitch)","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Bergerak berlawanan arah dengan hembusan angin","D. Menolong orang lain di setiap kesempatan"]', 'C. Bergerak berlawanan arah dengan hembusan angin'),
(5, 'Cerita Api Unggun ke-15 dan 16 membahas apresiasi terhadap lingkungan hidup, yakni tentang pengetahuan...', '["A. Simpul Tiang (Bowline)","B. Binatang dan Tumbuh-tumbuhan","C. Perkemahan (Camping)","D. Simpul Mati (Reef Knot)"]', 'B. Binatang dan Tumbuh-tumbuhan'),
(5, 'Prinsip konservasi dalam kepanduan menyatakan bahwa seorang Pramuka dilarang keras membunuh binatang apa pun, KECUALI...', '["A. Ing Ngarso Sung Tulodo","B. Be Prepared (Selalu Siap)","C. Trisatya dan Dasadarma","D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan"]', 'D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan'),
(5, 'Pengetahuan seorang Pramuka dalam mengenali berbagai jenis pohon liar, dedaunan, dan akar yang bisa dimakan sangat menunjang kemampuannya dalam bidang...', '["A. Survival (Bertahan Hidup)","B. Lord Edward Cecil","C. Mencari dan Mengikuti Jejak (Tracking)","D. Masakan di Perkemahan (Camp Cooking)"]', 'A. Survival (Bertahan Hidup)'),
(5, 'Cerita Api Unggun ke-17 berjudul "Bagaimana Supaya Kuat", yang memberikan instruksi agar kaum muda terbiasa menjaga...', '["A. 6 sampai 8 orang","B. Bergerak berlawanan arah dengan hembusan angin","C. Kesehatan fisik dan kebugaran tubuh","D. Simpul Anyam (Sheet Bend)"]', 'C. Kesehatan fisik dan kebugaran tubuh'),
(5, 'Untuk melatih kebugaran tubuh setiap hari, Baden-Powell menyarankan rutinitas senam pagi yang dikenal sebagai...', '["A. Masakan di Perkemahan (Camp Cooking)","B. 6 Latihan Fisik BP (BP Exercises)","C. Sistem Regu (Patrol System)","D. Warga negara yang aktif dan bermanfaat bagi negaranya"]', 'B. 6 Latihan Fisik BP (BP Exercises)'),
(5, 'Cerita Api Unggun ke-18 dan 19 mengulas tentang kebiasaan yang menyehatkan serta pencegahan penyakit. Baden-Powell sangat mewajibkan pandu bernapas dengan benar melalui...', '["A. Hidung, bukan mulut","B. Pingsan","C. Luka Bakar","D. Hipotermia"]', 'A. Hidung, bukan mulut'),
(5, 'Penyakit yang sering menyerang anggota perkemahan akibat meminum air mentah atau lingkungan perkemahan yang kurang bersih (sanitasi buruk) adalah...', '["A. Patah Tulang","B. Terkilir","C. Pingsan","D. Diare dan Disentri"]', 'D. Diare dan Disentri'),
(5, 'Cerita Api Unggun ke-20 bertemakan "Sikap Kesatria" (Chivalry). Inspirasi utama Baden-Powell dalam membentuk karakter Pramuka ini berasal dari legenda pahlawan kuno, yaitu...', '["A. Melakukan tekanan langsung pada area luka / balut tekan","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Warga negara yang aktif dan bermanfaat bagi negaranya","D. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)"]', 'B. Kesatria Meja Bundar (Knights of the Round Table)'),
(5, 'Raja legendaris Inggris yang memimpin para kesatria mulia dalam perumpamaan Baden-Powell tersebut adalah...', '["A. Jalan ke arah kanan","B. Survival (Bertahan Hidup)","C. Raja Arthur","D. Simpul Pangkal (Clove Hitch)"]', 'C. Raja Arthur'),
(5, 'Tokoh orang suci pelindung Inggris (Patron Saint) yang juga dijadikan sebagai pelindung simbolis kaum pandu di seluruh dunia karena keberaniannya membunuh naga adalah...', '["A. Santo George (St. George)","B. Soenardjo Atmodipuro","C. W.R. Supratman","D. Lord Robert Baden Powell"]', 'A. Santo George (St. George)'),
(5, 'Hari peringatan St. George, yang sering dirayakan secara internasional oleh anggota Pramuka sebagai ajang pembaruan Janji Pramuka, jatuh pada tanggal...', '["A. 26 April","B. 23 April","C. 21 April","D. 22 April"]', 'B. 23 April'),
(5, 'Cerita Api Unggun ke-21 menekankan pada konsep utama watak yang membuat seorang pandu dihormati, yaitu...', '["A. Survival (Bertahan Hidup)","B. Binatang dan Tumbuh-tumbuhan","C. Disiplin","D. Perkemahan (Camping)"]', 'C. Disiplin'),
(5, 'Ciri sejati dari kedisiplinan seorang Pramuka saat menerima instruksi dari pimpinannya adalah...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","C. 6 Latihan Fisik BP (BP Exercises)","D. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut"]', 'A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh'),
(5, 'Cerita Api Unggun ke-22 berjudul "Memperbaiki Diri". Hal ini mengajarkan filosofi bahwa seorang pandu sejati harus...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Melakukan tekanan langsung pada area luka / balut tekan","C. Dekat sumber air bersih dan aman dari bahaya alam","D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna"]', 'D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna'),
(5, 'Cerita Api Unggun ke-23 dan 24 membahas tentang keterampilan vital yang harus dimiliki setiap Pramuka jika terjadi insiden darurat, yakni tentang...', '["A. Patah Tulang","B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","C. Pingsan","D. Hipotermia"]', 'B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)'),
(5, 'Kaidah terpenting dan pertama kali yang harus dikuasai secara mental saat seorang Pramuka menghadapi situasi kecelakaan parah adalah...', '["A. Tetap tenang dan tidak panik","B. Selatan","C. Barat Laut","D. Barat Daya"]', 'A. Tetap tenang dan tidak panik'),
(5, 'Apabila menemui korban yang mengalami pendarahan hebat (luka terbuka memancar), tindakan Pertolongan Pertama yang paling efektif dilakukan adalah...', '["A. Luka Bakar","B. Disentri","C. Melakukan tekanan langsung pada area luka / balut tekan","D. Hipotermia"]', 'C. Melakukan tekanan langsung pada area luka / balut tekan'),
(5, 'Jika pakaian yang dikenakan oleh seseorang tiba-tiba tersambar api dan terbakar, tindakan penyelematan yang paling tepat diinstruksikan oleh Pramuka adalah...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","C. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna","D. Kesatria Meja Bundar (Knights of the Round Table)"]', 'B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal'),
(5, 'Cerita Api Unggun ke-25 mengingatkan tentang tujuan mulia kehadiran gerakan Pramuka dalam masyarakat, yaitu kewajiban untuk...', '["A. 6 sampai 8 orang","B. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","C. Be Prepared (Selalu Siap)","D. Menolong orang lain di setiap kesempatan"]', 'D. Menolong orang lain di setiap kesempatan'),
(5, 'Sebuah tradisi pandu yang diajarkan oleh Baden-Powell untuk melakukan setidaknya satu kebaikan kecil setiap harinya tanpa mengharap imbalan disebut dengan istilah...', '["A. Good Turn (Berbuat Kebaikan)","B. Pionering / Kepeloporan","C. Diare dan Disentri","D. Patrol Leader"]', 'A. Good Turn (Berbuat Kebaikan)'),
(5, 'Cerita Api Unggun ke-26, yang menjadi bab pamungkas dalam materi buku Scouting for Boys, secara umum membahas tentang sikap tanggung jawab bermasyarakat, yakni...', '["A. The Jungle Book","B. Kewarganegaraan (Citizenship)","C. Boyman","D. Rovering to Success"]', 'B. Kewarganegaraan (Citizenship)'),
(5, 'Inti dari jiwa kewarganegaraan seorang Pramuka adalah kemauannya untuk memahami sejarah, pemerintahan, dan hukum bangsanya, agar kelak ia menjadi...', '["A. Timur","B. Barat Laut","C. Warga negara yang aktif dan bermanfaat bagi negaranya","D. Selatan"]', 'C. Warga negara yang aktif dan bermanfaat bagi negaranya'),
(5, 'Semboyan kepanduan utama yang diperkenalkan Baden-Powell dalam buku ini, yang wajib dipraktikkan baik dalam kesiapan fisik maupun mental oleh pandu di seluruh dunia adalah...', '["A. Be Prepared (Selalu Siap)","B. Olave St. Clair Soames","C. Lord Edward Cecil","D. Agnes Baden-Powell"]', 'A. Be Prepared (Selalu Siap)'),
(5, 'Pesan moral secara keseluruhan dari Scouting for Boys yang tercantum di Bab 5 Boyman adalah membentuk remaja agar tidak hanya menjadi sosok petualang alam bebas, tetapi juga menjadi...', '["A. Dekat sumber air bersih dan aman dari bahaya alam","B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","C. 6 Latihan Fisik BP (BP Exercises)","D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia"]', 'D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia'),

-- ==========================================
-- BAB 9: Berkemah / Alam Bebas
-- ==========================================
(9, 'Pengertian berkemah dalam kepramukaan pada dasarnya adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","C. Tenda, alat masak regu (nesting), dan kotak P3K regu","D. Dekat dengan sumber air yang bersih dan aman dari bahaya alam"]', 'B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung'),
(9, 'Salah satu sasaran dan motivasi utama dari kegiatan berkemah bagi anggota Pramuka adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","D. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang"]', 'A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka'),
(9, 'Tahap pertama yang mutlak harus dilakukan sebelum menyelenggarakan kegiatan perkemahan adalah...', '["A. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","C. Menyalakan api, kompor, lentera minyak, atau lilin","D. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)"]', 'B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)'),
(9, 'Syarat utama tapak kemah (lokasi perkemahan) yang baik dan aman adalah...', '["A. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","D. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga"]', 'B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam'),
(9, 'Mengapa mendirikan tenda di dasar cekungan (lembah sempit) sangat dilarang dalam aturan perkemahan?', '["A. Ponco","B. Groundsheet / Terpal","C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","D. Survival Kit"]', 'C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air'),
(9, 'Mendirikan tenda di bawah pohon tua yang sudah lapuk sangat dihindari karena...', '["A. Survival Kit","B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","C. Nesting","D. Ponco"]', 'B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang'),
(9, 'Arah pintu tenda yang ideal saat didirikan di alam bebas sebaiknya...', '["A. Selatan","B. Membelakangi atau menyamping dari arah hembusan angin utama","C. Barat Laut","D. Utara"]', 'B. Membelakangi atau menyamping dari arah hembusan angin utama'),
(9, 'Tujuan utama membuat parit kecil di sekeliling tenda saat berkemah adalah...', '["A. Survival Kit","B. Nesting","C. Mencegah air hujan masuk/menggenangi bagian dalam tenda","D. Ponco"]', 'C. Mencegah air hujan masuk/menggenangi bagian dalam tenda'),
(9, 'Tenda darurat sementara yang dibuat dari bahan alam atau jas hujan (ponco) dinamakan...', '["A. Bivak","B. Disentri","C. Hipotermia","D. Patah Tulang"]', 'A. Bivak'),
(9, 'Tenda standar beregu yang sering digunakan oleh Pramuka Penggalang, bentuknya seperti rumah dengan atap segitiga disebut...', '["A. Flysheet","B. Survival Kit","C. Tenda Prisma (Tenda Regu)","D. Groundsheet / Terpal"]', 'C. Tenda Prisma (Tenda Regu)'),
(9, 'Agar patok (pasak) tenda menancap kuat menahan tarikan tali, kemiringan pasak yang ditancapkan ke tanah sebaiknya bersudut...', '["A. Sleeping Bag (Kantong Tidur)","B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Ransel (Carrier / Backpack)","D. Flysheet"]', 'B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(9, 'Simpul yang paling tepat digunakan untuk mengikatkan tali tenda pada pasak agar mudah dikencangkan dan dikendurkan adalah...', '["A. Simpul Mati (Reef Knot)","B. Ikatan Silang","C. Simpul Delapan","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'D. Simpul Tali Tenda (Taut-line Hitch)'),
(9, 'Perlengkapan perkemahan dibagi menjadi dua macam, yaitu...', '["A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","B. Flysheet","C. Groundsheet / Terpal","D. Ponco"]', 'A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Pribadi saat berkemah adalah...', '["A. Tenda Prisma","B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","C. Nesting","D. Matras"]', 'B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Regu adalah...', '["A. Groundsheet / Terpal","B. Ponco","C. Tenda, alat masak regu (nesting), dan kotak P3K regu","D. Nesting"]', 'C. Tenda, alat masak regu (nesting), dan kotak P3K regu'),
(9, 'Alat pelindung tubuh dari suhu dingin saat tidur di dalam tenda yang bentuknya seperti kepompong disebut...', '["A. Ransel (Carrier / Backpack)","B. Sleeping Bag (Kantong Tidur)","C. Nesting","D. Groundsheet / Terpal"]', 'B. Sleeping Bag (Kantong Tidur)'),
(9, 'Alat berupa alas tidur berbahan busa/spons yang berfungsi menahan hawa dingin dari tanah agar tidak langsung mengenai tubuh disebut...', '["A. Ransel (Carrier / Backpack)","B. Matras","C. Nesting","D. Sleeping Bag (Kantong Tidur)"]', 'B. Matras'),
(9, 'Tas besar khusus untuk membawa perlengkapan berkemah yang bentuknya dirancang mengikuti anatomi punggung disebut...', '["A. Sleeping Bag (Kantong Tidur)","B. Nesting","C. Ransel (Carrier / Backpack)","D. Ponco"]', 'C. Ransel (Carrier / Backpack)'),
(9, 'Prinsip dasar saat melakukan "Packing" (mengepak barang ke dalam ransel) agar tidak membuat punggung cepat lelah adalah...', '["A. Good Turn (Berbuat Kebaikan)","B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","C. Trisatya dan Dasadarma","D. Dwisatya dan Dwidarma"]', 'B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung'),
(9, 'Selain masalah berat, prinsip "Packing" yang baik untuk melindungi barang dari hujan adalah...', '["A. Be Prepared (Selalu Siap)","B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","C. Satyaku Kudarmakan, Darmaku Kubaktikan","D. Dwisatya dan Dwidarma"]', 'B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang'),
(9, 'Jas hujan berukuran besar berbentuk kelelawar yang dapat dialihfungsikan sebagai atap bivak darurat dinamakan...', '["A. Demam Berdarah","B. Diare","C. Ponco","D. Disentri"]', 'C. Ponco'),
(9, 'Syarat bahan makanan yang ideal untuk dibawa saat perkemahan adalah...', '["A. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung"]', 'B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak'),
(9, 'Alat masak portabel berbahan aluminium yang sering digunakan oleh militer dan pramuka karena bisa disusun menjadi satu wadah ringkas disebut...', '["A. Barung","B. Kwartir","C. Nesting","D. Gugus Depan"]', 'C. Nesting'),
(9, 'Lokasi yang TEPAT untuk menyalakan perapian atau kompor saat berkemah adalah...', '["A. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan"]', 'C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering'),
(9, 'Hal yang mutlak DILARANG dilakukan di dalam tenda karena sangat berbahaya adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Tenda Prisma","C. Survival Kit","D. Ransel (Carrier / Backpack)"]', 'A. Menyalakan api, kompor, lentera minyak, atau lilin'),
(9, 'Pembuatan fasilitas MCK (Mandi Cuci Kakus) darurat di area kemah harus berjarak minimal...', '["A. Luka Bakar","B. Pendarahan","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Disentri"]', 'C. 15-20 meter dari sumber air agar tidak mencemari mata air'),
(9, 'Manajemen sampah di area perkemahan untuk jenis sampah anorganik (plastik, kaleng, kaca) yang paling benar adalah...', '["A. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","C. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)'),
(9, 'Sampah organik (sisa makanan) di area perkemahan sebaiknya...', '["A. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan","C. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","D. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering"]', 'B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan'),
(9, 'Saat mengambil air minum dari sungai atau mata air alam, langkah wajib yang harus dilakukan sebelum meminumnya adalah...', '["A. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","D. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka"]', 'B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri'),
(9, 'Api unggun dalam kegiatan perkemahan memiliki fungsi utama sebagai...', '["A. Ransel (Carrier / Backpack)","B. Sarana persaudaraan, kehangatan, dan pertunjukan seni","C. Simpul Tali Tenda (Taut-line Hitch)","D. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda"]', 'B. Sarana persaudaraan, kehangatan, dan pertunjukan seni'),
(9, 'Aturan utama dalam membuat api unggun di alam bebas agar tidak merusak lingkungan adalah...', '["A. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","B. 15-20 meter dari sumber air agar tidak mencemari mata air","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang"]', 'C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya'),
(9, 'Pakaian lapangan yang ideal untuk berkemah adalah...', '["A. 15-20 meter dari sumber air agar tidak mencemari mata air","B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","C. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","D. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri"]', 'B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)'),
(9, 'Mengapa celana berbahan Jeans/Denim SANGAT TIDAK disarankan dipakai untuk kegiatan kemah di alam bebas?', '["A. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","D. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang"]', 'B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)'),
(9, 'Jenis alas kaki yang paling aman untuk kegiatan perkemahan dan penjelajahan adalah...', '["A. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","B. Sarana persaudaraan, kehangatan, dan pertunjukan seni","C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)","D. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat"]', 'C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)'),
(9, 'Lembaran kain sintetis kedap air yang sering dipasang di atas tenda untuk menahan air hujan atau dibuat sebagai atap teras dinamakan...', '["A. Flysheet","B. Ki Hajar Dewantara","C. Mayor Kenneth McLaren","D. Agnes Baden-Powell"]', 'A. Flysheet'),
(9, 'Alat kedap air yang diletakkan di bawah (lantai dasar) tenda agar uap air dari tanah tidak tembus ke dalam dinamakan...', '["A. H. Mutahar","B. Groundsheet / Terpal","C. Ki Hajar Dewantara","D. Mayor Kenneth McLaren"]', 'B. Groundsheet / Terpal'),
(9, 'Aturan keamanan saat memegang dan berjalan membawa senjata tajam (golok/pisau) di perkemahan adalah...', '["A. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","B. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","D. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung"]', 'C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya'),
(9, 'Saat ada anggota yang bertugas piket jaga malam, posisi jaga yang paling benar adalah...', '["A. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","C. Membelakangi atau menyamping dari arah hembusan angin utama","D. Tenda, alat masak regu (nesting), dan kotak P3K regu"]', 'B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat'),
(9, 'Jika tenda bocor parah di tengah hujan badai malam hari dan seluruh pakaian basah kuyup, ancaman kesehatan paling berbahaya adalah...', '["A. Barat Laut","B. Hipotermia","C. Timur","D. Timur Laut"]', 'B. Hipotermia'),
(9, 'Etika perkemahan saat malam hari (Quiet Hours) mengharuskan seluruh anggota untuk...', '["A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","D. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu"]', 'A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain'),
(9, 'Langkah pertama saat akan membongkar tenda di akhir kegiatan kemah adalah...', '["A. Tenda Prisma","B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","C. Groundsheet / Terpal","D. Ponco"]', 'B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda'),
(9, 'Syarat utama sebelum melipat kain tenda untuk disimpan ke dalam tas adalah...', '["A. Matras","B. Survival Kit","C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","D. Flysheet"]', 'C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur'),
(9, 'Prinsip pencinta alam "Leave No Trace" (Jangan tinggalkan jejak) mengajarkan kita untuk...', '["A. Ikhlas Bakti Bina Bangsa","B. Dwisatya dan Dwidarma","C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","D. Satyaku Kudarmakan, Darmaku Kubaktikan"]', 'C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang'),
(9, 'Kotak atau tas darurat berukuran kecil berisi perlengkapan bertahan hidup esensial (seperti korek anti air, kail pancing, pisau lipat, plester) dinamakan...', '["A. Pingsan","B. Survival Kit","C. Patah Tulang","D. Disentri"]', 'B. Survival Kit'),
(9, 'Tindakan yang benar jika tersesat saat melakukan kegiatan penjelajahan di sekitar perkemahan adalah...', '["A. Mencegah air hujan masuk/menggenangi bagian dalam tenda","B. STOP (Stop, Think, Observe, Plan) dan tidak panik","C. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","D. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur"]', 'B. STOP (Stop, Think, Observe, Plan) dan tidak panik'),
(9, 'Fungsi menggunakan pakaian lengan panjang saat menerobos semak/hutan di area kemah adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","C. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","D. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat"]', 'B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga'),
(9, 'Tanda yang dibuat oleh anggota Pramuka menggunakan batu, ranting, atau goresan tanah untuk memberi petunjuk arah di alam bebas disebut...', '["A. Barat Laut","B. Tanda Jejak","C. Barat","D. Selatan"]', 'B. Tanda Jejak'),
(9, 'Sikap mental yang paling dituntut dari seorang pemimpin regu saat perkemahan dilanda cuaca buruk adalah...', '["A. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu","D. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka"]', 'C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu'),
(9, 'Obat yang wajib dibawa secara pribadi (tidak boleh mengandalkan regu) saat berkemah adalah...', '["A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)","D. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda"]', 'B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri'),
(9, 'Tujuan akhir setelah kembali dari kegiatan berkemah adalah...', '["A. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung"]', 'B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari'),

-- ==========================================
-- BAB 12: Sandi Morse (Komunikasi)
-- ==========================================
(12, 'Kata "Sandi" berasal dari bahasa Sanskerta, yang memiliki arti...', '["A. Tulisan","B. Rahasia","C. Isyarat","D. Pesan"]', 'B. Rahasia'),
(12, 'Fungsi utama mempelajari sandi dalam kegiatan kepramukaan adalah untuk...', '["A. Berlawanan / Berkebalikan (Contoh: A >< N)","B. Melatih daya ingat, kecerdasan, dan ketelitian","C. Garis miring ganda (//)","D. Samuel F.B. Morse"]', 'B. Melatih daya ingat, kecerdasan, dan ketelitian'),
(12, 'Penemu sistem telegraf dan kode Morse adalah seorang seniman dan penemu asal Amerika yang bernama...', '["A. Agnes Baden-Powell","B. Samuel F.B. Morse","C. Rudyard Kipling","D. Andri Bob Sunardi"]', 'B. Samuel F.B. Morse'),
(12, 'Kode Morse pertama kali ditemukan dan digunakan secara praktis pada tahun...', '["A. 1837","B. 1842","C. 1835","D. 1834"]', 'A. 1837'),
(12, 'Dalam standar internasional, perbandingan durasi waktu antara bunyi/simbol "titik" dan "garis" pada sandi Morse adalah...', '["A. Titik","B. 1 : 3","C. ........","D. .-.."]', 'B. 1 : 3'),
(12, 'Huruf yang direpresentasikan dengan satu titik (.) dalam sandi Morse adalah...', '["A. I","B. E","C. S","D. T"]', 'B. E'),
(12, 'Huruf yang direpresentasikan dengan satu garis (-) dalam sandi Morse adalah...', '["A. E","B. M","C. T","D. N"]', 'C. T'),
(12, 'Kode Morse untuk huruf "A" adalah...', '["A. .-","B. K","C. Y","D. Z"]', 'A. .-'),
(12, 'Kode Morse untuk huruf "B" adalah...', '["A. -...","B. L","C. J","D. N"]', 'A. -...'),
(12, 'Sinyal marabahaya darurat atau minta tolong standar internasional (SOS) dalam sandi Morse ditulis dengan...', '["A. --- .-. ---","B. ... --- ...","C. ... .-. ...","D. --- ... ---"]', 'B. ... --- ...'),
(12, 'Kode Morse (...--) melambangkan angka...', '["A. 7","B. 7","C. 3","D. 6"]', 'C. 3'),
(12, 'Kode Morse (---..) melambangkan angka...', '["A. 10","B. 7","C. 8","D. 11"]', 'C. 8'),
(12, 'Kode Morse (----.) melambangkan angka...', '["A. 12","B. 11","C. 9","D. 14"]', 'C. 9'),
(12, 'Tanda pemisah antar kata saat menulis sandi Morse di atas kertas biasanya menggunakan tanda...', '["A. Melatih daya ingat, kecerdasan, dan ketelitian","B. Garis miring ganda (//)","C. Tiga garis (---)","D. ... --- ..."]', 'B. Garis miring ganda (//)'),
(12, 'Dalam pengiriman pesan Morse, tanda untuk memulai panggilan atau "Attention" biasanya menggunakan kode...', '["A. -.-.-.","B. -...","C. .-..","D. -.."]', 'A. -.-.-.'),
(12, 'Isyarat bahwa "Pesan Selesai" (End of Message) dalam pengiriman Morse ditandai dengan kode gabungan huruf AR, yaitu...', '["A. .-.-.","B. L","C. Q","D. I"]', 'A. .-.-.'),
(12, 'Jika pengirim melakukan kesalahan saat mengirim sandi Morse, ia memberikan isyarat salah (E 8 kali) yang berbunyi...', '["A. .--.","B. ........","C. ..-","D. -.-."]', 'B. ........'),
(12, 'Huruf yang secara kode berlawanan dengan A (.-) adalah N, yaitu...', '["A. -.","B. B","C. P","D. Y"]', 'A. -.'),
(12, 'Huruf "O" dalam sandi Morse terdiri dari...', '["A. Tiga garis (---)","B. M","C. U","D. T"]', 'A. Tiga garis (---)'),
(12, 'Huruf "S" dalam sandi Morse terdiri dari...', '["A. Tiga titik (...)","B. D","C. F","D. Q"]', 'A. Tiga titik (...)'),
(12, 'Gabungan huruf S dan O membentuk kata SOS, yang secara universal berarti isyarat...', '["A. R","B. Darurat / Marabahaya","C. B","D. W"]', 'B. Darurat / Marabahaya'),
(12, 'Huruf "I" dalam sandi Morse terdiri dari...', '["A. W","B. G","C. Dua titik (..)","D. Q"]', 'C. Dua titik (..)'),
(12, 'Huruf "M" dalam sandi Morse terdiri dari...', '["A. E","B. Dua garis (--)","C. Y","D. B"]', 'B. Dua garis (--)'),
(12, 'Huruf "C" dalam sandi Morse dituliskan dengan kode...', '["A. -.-.","B. T","C. S","D. R"]', 'A. -.-.'),
(12, 'Huruf "D" dalam sandi Morse dituliskan dengan kode...', '["A. Q","B. -..","C. O","D. J"]', 'B. -..'),
(12, 'Berlawanan dengan huruf D (-..), huruf "U" dalam sandi morse adalah...', '["A. ..-","B. R","C. O","D. D"]', 'A. ..-'),
(12, 'Huruf "F" dalam sandi Morse adalah...', '["A. ..-.","B. K","C. S","D. T"]', 'A. ..-.'),
(12, 'Huruf "G" dalam sandi Morse adalah...', '["A. X","B. --.","C. G","D. U"]', 'B. --.'),
(12, 'Huruf "H" dalam sandi Morse adalah...', '["A. I","B. L","C. S","D. ...."]', 'D. ....'),
(12, 'Huruf "J" dalam sandi Morse adalah...', '["A. L","B. Y","C. .---","D. M"]', 'C. .---'),
(12, 'Huruf "K" dalam sandi Morse adalah...', '["A. -.-","B. S","C. G","D. R"]', 'A. -.-'),
(12, 'Huruf "L" dalam sandi Morse adalah...', '["A. M","B. .-..","C. X","D. G"]', 'B. .-..'),
(12, 'Huruf "P" dalam sandi Morse adalah...', '["A. R","B. U","C. .--.","D. D"]', 'C. .--.'),
(12, 'Huruf "Q" dalam sandi Morse adalah...', '["A. --.-","B. M","C. D","D. F"]', 'A. --.-'),
(12, 'Huruf "R" dalam sandi Morse adalah...', '["A. R","B. .-.","C. L","D. Y"]', 'B. .-.'),
(12, 'Huruf "V" dalam sandi Morse adalah...', '["A. M","B. X","C. ...-","D. K"]', 'C. ...-'),
(12, 'Huruf "W" dalam sandi Morse adalah...', '["A. .--","B. E","C. G","D. W"]', 'A. .--'),
(12, 'Huruf "X" dalam sandi Morse adalah...', '["A. Y","B. -..-","C. B","D. U"]', 'B. -..-'),
(12, 'Huruf "Y" dalam sandi Morse adalah...', '["A. G","B. X","C. -.--","D. L"]', 'C. -.--'),
(12, 'Huruf "Z" dalam sandi Morse adalah...', '["A. --..","B. O","C. D","D. Q"]', 'A. --..'),
(12, 'Angka 1 dalam sandi Morse ditulis dengan urutan...', '["A. --.","B. .----","C. --.-","D. ...-"]', 'B. .----'),
(12, 'Angka 5 dalam sandi Morse adalah...', '["A. .--","B. .---","C. .....","D. -"]', 'C. .....'),
(12, 'Angka 0 dalam sandi Morse adalah...', '["A. -----","B. -.","C. .-.","D. -.-"]', 'A. -----'),
(12, 'Tanda koma (,) dalam tulisan Morse diwakili dengan gabungan...', '["A. .--.","B. --..--","C. .-","D. ..."]', 'B. --..--'),
(12, 'Tanda tanya (?) dalam tulisan Morse diwakili dengan gabungan...', '["A. ..--..","B. --.","C. --","D. ..."]', 'A. ..--..'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan pendek secara internasional mewakili...', '["A. Titik","B. Dua garis (--)","C. Darurat / Marabahaya","D. .-.-."]', 'A. Titik'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan panjang yang keras mewakili...', '["A. E","B. Garis","C. -..-","D. Samuel F.B. Morse"]', 'B. Garis'),
(12, 'Isyarat komunikasi "Tunggu" (AS) yang dikirimkan kepada lawan saat transmisi Morse adalah...', '["A. -...","B. ..","C. .-...","D. -"]', 'C. .-...'),
(12, 'Isyarat "Mengerti / Pesan Diterima" (R) yang dikirimkan kembali oleh penerima pesan adalah...', '["A. .-.","B. --.","C. .","D. -.-"]', 'A. .-.'),
(12, 'Cara paling mudah dan umum yang diajarkan dalam pramuka untuk menghafal sandi Morse adalah metode pengelompokan huruf yang saling...', '["A. C","B. Berlawanan / Berkebalikan (Contoh: A >< N)","C. U","D. H"]', 'B. Berlawanan / Berkebalikan (Contoh: A >< N)'),

-- ==========================================
-- BAB 15: Membaca Peta & Navigasi
-- ==========================================
(15, 'Gambar seluruh atau sebagian permukaan bumi yang diproyeksikan pada bidang datar dengan perbandingan skala tertentu disebut...', '["A. Greenwich, London, Inggris","B. Peta","C. Skala Garis (Grafis)","D. Landai / Datar"]', 'B. Peta'),
(15, 'Jenis peta yang sangat penting bagi Pramuka karena menggambarkan tinggi rendahnya permukaan bumi (relief) secara detail adalah...', '["A. Garis Kontur","B. Peta Topografi","C. Deklinasi","D. Legenda Peta"]', 'B. Peta Topografi'),
(15, 'Kumpulan penjelasan tentang arti simbol-simbol dan warna yang terdapat pada peta disebut...', '["A. Ungu","B. Putih","C. Hijau","D. Legenda Peta"]', 'D. Legenda Peta'),
(15, 'Angka yang menunjukkan perbandingan antara jarak di atas peta dengan jarak sebenarnya di lapangan disebut...', '["A. Curvimeter","B. Resection","C. Skala","D. Northing"]', 'C. Skala'),
(15, 'Peta dengan skala 1 : 25.000 berarti 1 cm pada peta mewakili jarak sebenarnya di lapangan sejauh...', '["A. 255 meter","B. 250 meter","C. 251 meter","D. 249 meter"]', 'B. 250 meter'),
(15, 'Jika jarak antara titik A dan B di peta topografi (skala 1:50.000) adalah 4 cm, maka jarak sebenarnya di lapangan adalah...', '["A. 1 kilometer","B. 2 kilometer","C. 1 kilometer","D. 5 kilometer"]', 'B. 2 kilometer'),
(15, 'Skala peta yang ditunjukkan dalam bentuk garis lurus yang terbagi menjadi beberapa ruas dengan ukuran satuan jarak tertentu disebut...', '["A. Indeks Kontur","B. Garis Kontur","C. Skala Garis (Grafis)","D. Orientasi Peta"]', 'C. Skala Garis (Grafis)'),
(15, 'Garis khayal melingkar pada peta topografi yang menghubungkan titik-titik dengan ketinggian yang sama dari permukaan laut disebut...', '["A. Peta Topografi","B. Intersection","C. Garis Kontur","D. Indeks Kontur"]', 'C. Garis Kontur'),
(15, 'Ciri khas utama dari garis kontur adalah jika jarak antar garisnya tergambar sangat rapat, hal itu menunjukkan bentuk medan yang...', '["A. Resection","B. Curam / Terjal","C. Legenda Peta","D. Protractor"]', 'B. Curam / Terjal'),
(15, 'Jika jarak antar garis kontur di peta terlihat renggang atau saling berjauhan, itu menandakan bentuk medan yang...', '["A. Peta Topografi","B. Easting","C. Landai / Datar","D. Skala"]', 'C. Landai / Datar'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" terbalik yang menjorok ke arah ketinggian (menunjuk ke tempat yang lebih tinggi) menandakan bentang alam berupa...', '["A. Z","B. Lembah / Aliran Sungai","C. S","D. V"]', 'B. Lembah / Aliran Sungai'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" yang menjorok ke arah tempat yang lebih rendah menandakan bentang alam berupa...', '["A. B","B. Punggungan (Sadel) / Punggung Bukit","C. Y","D. L"]', 'B. Punggungan (Sadel) / Punggung Bukit'),
(15, 'Garis kontur yang tergambar berupa lingkaran-lingkaran kecil konsentris yang semakin mengecil di bagian tengah biasanya menandakan...', '["A. Puncak bukit / Gunung","B. Orientasi Peta","C. UTM","D. Intersection"]', 'A. Puncak bukit / Gunung'),
(15, 'Jika ada garis kontur melingkar namun memiliki garis-garis rambut kecil (tick marks) yang mengarah ke bagian dalam lingkaran, itu menandakan...', '["A. Tenggara","B. Barat Daya","C. Depresi / Kawah / Cekungan","D. Barat Laut"]', 'C. Depresi / Kawah / Cekungan'),
(15, 'Selisih ketinggian atau jarak vertikal antara satu garis kontur dengan garis kontur di sebelahnya disebut...', '["A. Resection","B. Interval Kontur","C. Indeks Kontur","D. Deklinasi"]', 'B. Interval Kontur'),
(15, 'Garis kontur yang biasanya dicetak lebih tebal dan disertai angka penunjuk ketinggian untuk mempermudah pembacaan peta disebut...', '["A. UTM","B. Legenda Peta","C. Indeks Kontur","D. Curvimeter"]', 'C. Indeks Kontur'),
(15, 'Sistem garis kisi-kisi (grid) yang membagi peta menjadi kotak-kotak untuk menentukan posisi secara akurat dinamakan koordinat...', '["A. Peta Topografi","B. Orientasi Peta","C. UTM (Universal Transverse Mercator)","D. Indeks Kontur"]', 'C. UTM (Universal Transverse Mercator)'),
(15, 'Garis vertikal (membujur dari bawah ke atas) pada sistem koordinat kotak (grid) peta yang angkanya dibaca pertama kali (dibaca ke arah Timur) disebut...', '["A. Barat Laut","B. Easting","C. Barat","D. Timur"]', 'B. Easting'),
(15, 'Garis horizontal (melintang dari kiri ke kanan) pada sistem koordinat grid peta yang angkanya dibaca kedua (dibaca ke arah Utara) disebut...', '["A. Utara","B. Northing","C. Barat Daya","D. Timur Laut"]', 'B. Northing'),
(15, 'Aturan emas (golden rule) dalam membaca koordinat grid di atas peta topografi adalah...', '["A. Garis Kontur","B. Orientasi Peta","C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","D. UTM"]', 'C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)'),
(15, 'Jika kita diminta menunjuk titik dengan koordinat 6 digit (contoh: 456 789), ini berarti tingkat ketelitian pencarian lokasi tersebut mencapai area seluas...', '["A. Resection","B. 100 meter persegi","C. Garis Kontur","D. Skala"]', 'B. 100 meter persegi'),
(15, 'Arah Utara yang ditunjukkan oleh garis-garis grid vertikal lurus ke atas pada peta disebut...', '["A. Barat Daya","B. Timur Laut","C. Utara Peta (Grid North)","D. Tenggara"]', 'C. Utara Peta (Grid North)'),
(15, 'Arah Utara yang mengarah tepat ke Kutub Utara bumi (poros rotasi) disebut...', '["A. Timur Laut","B. Timur","C. Utara Sebenarnya (True North)","D. Barat Laut"]', 'C. Utara Sebenarnya (True North)'),
(15, 'Dalam legenda peta topografi standar, warna COKLAT umumnya digunakan untuk menggambarkan...', '["A. Biru","B. Merah","C. Garis ketinggian (Kontur) dan bentang alam darat","D. Abu-abu"]', 'C. Garis ketinggian (Kontur) dan bentang alam darat'),
(15, 'Warna HIJAU pada peta topografi selalu mengindikasikan adanya...', '["A. Coklat","B. Kawasan vegetasi / Hutan / Perkebunan","C. Hijau","D. Putih"]', 'B. Kawasan vegetasi / Hutan / Perkebunan'),
(15, 'Warna BIRU pada peta digunakan secara universal untuk menyimbolkan unsur...', '["A. Kuning","B. Ungu","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. Biru"]', 'C. Hidrografi / Perairan (Sungai, danau, rawa, laut)'),
(15, 'Warna MERAH pada peta topografi sering kali dikhususkan untuk menandakan unsur penting buatan manusia, yaitu...', '["A. Hitam","B. Jalan raya utama / aspal","C. Merah","D. Putih"]', 'B. Jalan raya utama / aspal'),
(15, 'Warna HITAM dalam peta biasanya digunakan untuk mencetak...', '["A. Merah","B. Hijau","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Putih"]', 'C. Simbol pemukiman, gedung, jalan setapak, dan tulisan'),
(15, 'Simbol berupa titik hitam dengan bentuk segitiga atau lingkaran disertai angka (misal: ▲ 2100) di peta menunjukkan...', '["A. Skala","B. Titik Triangulasi / Ketinggian mutlak (Spot Height)","C. Curvimeter","D. Intersection"]', 'B. Titik Triangulasi / Ketinggian mutlak (Spot Height)'),
(15, 'Tindakan menyamakan posisi arah Utara pada peta agar sejajar dengan arah Utara sebenarnya di lapangan (menggunakan kompas) disebut...', '["A. Orientasi Peta","B. Timur Laut","C. Barat Daya","D. Utara"]', 'A. Orientasi Peta'),
(15, 'Syarat pertama yang harus dilakukan sebelum melakukan teknik navigasi Resection atau Intersection di lapangan adalah...', '["A. Kawasan vegetasi / Hutan / Perkebunan","B. Melakukan Orientasi Peta terlebih dahulu","C. Utara Peta (Grid North)","D. 0 derajat lintang"]', 'B. Melakukan Orientasi Peta terlebih dahulu'),
(15, 'Teknik navigasi untuk menentukan titik koordinat posisi kita sendiri di atas peta, dengan cara membidik dua objek alam yang sudah diketahui di peta, disebut...', '["A. Curvimeter","B. Peta Topografi","C. Resection","D. Skala"]', 'C. Resection'),
(15, 'Teknik navigasi untuk mencari koordinat posisi objek lain (sasaran) yang belum diketahui di peta, dengan membidiknya dari dua titik stasiun yang berbeda, disebut...', '["A. Indeks Kontur","B. Intersection","C. Peta Topografi","D. Garis Kontur"]', 'B. Intersection'),
(15, 'Alat ukur sederhana berbentuk busur derajat berbentuk kotak persegi transparan yang digunakan untuk menghitung sudut dan koordinat langsung di atas peta disebut...', '["A. Deklinasi","B. Protractor","C. Garis Kontur","D. Protractor (Busur Peta)"]', 'D. Protractor (Busur Peta)'),
(15, 'Alat mekanis kecil dengan roda bergerigi yang dijalankan menyusuri rute lengkung di peta (seperti sungai atau jalan berliku) untuk menghitung jarak disebut...', '["A. Curvimeter","B. Intersection","C. Resection","D. Legenda Peta"]', 'A. Curvimeter'),
(15, 'Penyimpangan sudut yang terjadi antara garis Utara Peta (Grid) dengan Utara Magnetis (Kompas) di suatu wilayah disebut...', '["A. Deklinasi Magnetis","B. Selatan","C. Barat Daya","D. Barat Laut"]', 'A. Deklinasi Magnetis'),
(15, 'Jika kita melipat peta topografi untuk dibawa di saku lapangan, cara melipat yang benar agar peta tidak cepat rusak dan mudah dibaca adalah...', '["A. Curvimeter","B. Indeks Kontur","C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","D. Skala"]', 'C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar'),
(15, 'Saat membaca peta, jika kita berjalan mengikuti punggungan bukit (ridge), maka di peta kita sebenarnya sedang melangkah memotong garis-garis kontur yang berbentuk...', '["A. Garis Kontur","B. U atau V terbalik (menjorok ke bawah)","C. Skala","D. Legenda Peta"]', 'B. U atau V terbalik (menjorok ke bawah)'),
(15, 'Kumpulan peta dalam satu wujud buku besar dinamakan...', '["A. Atlas","B. Curvimeter","C. Protractor","D. Resection"]', 'A. Atlas'),
(15, 'Jika tidak memiliki meteran, seorang Pramuka dapat memperkirakan jarak di peta dengan di lapangan menggunakan teknik...', '["A. Menghitung jumlah langkah kaki ganda (Pacing)","B. Intersection","C. Resection","D. Orientasi Peta"]', 'A. Menghitung jumlah langkah kaki ganda (Pacing)'),
(15, 'Garis Khatulistiwa (Equator) yang membelah bumi menjadi Utara dan Selatan ditarik pada derajat...', '["A. 0 derajat lintang","B. Barat Laut","C. Tenggara","D. Timur Laut"]', 'A. 0 derajat lintang'),
(15, 'Garis Bujur Utama (Prime Meridian) yang menjadi titik 0 derajat dan patokan waktu bumi disepakati melintasi kota...', '["A. Afrika Selatan","B. Pulau Brownsea","C. Greenwich, London, Inggris","D. Olympia Hall"]', 'C. Greenwich, London, Inggris'),
(15, 'Informasi mengenai tahun pembuatan atau pembaruan peta (update) biasanya dapat ditemukan di...', '["A. Legenda Peta","B. Orientasi Peta","C. Bagian tepi bawah luar / Margin bawah peta","D. Easting"]', 'C. Bagian tepi bawah luar / Margin bawah peta'),
(15, 'Navigasi yang dilakukan di malam hari tanpa kompas dapat mengandalkan Rasi Bintang Pari (Crux) untuk menentukan arah...', '["A. Barat Laut","B. Selatan","C. Barat Daya","D. Tenggara"]', 'B. Selatan'),
(15, 'Navigasi malam hari di belahan bumi utara/tengah dapat menentukan arah Utara dengan mencari konstelasi bintang...', '["A. Ursa Major (Bintang Biduk) / Polaris","B. Selatan","C. Barat Laut","D. Tenggara"]', 'A. Ursa Major (Bintang Biduk) / Polaris'),
(15, 'Alasan mengapa lumut pada pohon lebih sering tumbuh tebal di sisi tertentu (sebagai navigasi darurat penunjuk Timur/Barat) adalah...', '["A. Hipotermia","B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","C. Diare","D. Demam Berdarah"]', 'B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)'),
(15, 'Metode navigasi alam menggunakan bayangan tongkat kayu yang ditancapkan tegak di tanah pada siang hari disebut metode...', '["A. LU (N - North)","B. Sundial / Metode Bayangan Matahari","C. Melakukan Orientasi Peta terlebih dahulu","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'B. Sundial / Metode Bayangan Matahari'),
(15, 'Pada peta dengan sistem koordinat grid geografis, Lintang Utara disingkat dengan huruf...', '["A. LU (N - North)","B. V","C. G","D. S"]', 'A. LU (N - North)'),
(15, 'Satu derajat (1°) dalam sistem koordinat Geografis (DMS) dibagi lagi menjadi...', '["A. 63 menit","B. 60 menit","C. 57 menit","D. 63 menit"]', 'B. 60 menit'),
(15, 'Sistem Penentuan Posisi Global yang mengandalkan perangkat elektronik untuk menerima sinyal satelit navigasi bumi disebut...', '["A. Melakukan Orientasi Peta terlebih dahulu","B. Puncak bukit / Gunung","C. GPS (Global Positioning System)","D. Jalan raya utama / aspal"]', 'C. GPS (Global Positioning System)'),

-- ==========================================
-- BAB 20: Macam-Macam Sandi
-- ==========================================
(20, 'Sandi yang menggunakan bentuk garis vertikal, horizontal, dan titik sebagai pengganti huruf disebut...', '["A. T","B. Sandi Kotak 1","C. S","D. C"]', 'B. Sandi Kotak 1'),
(20, 'Sandi Kotak 1 terdiri dari dua macam bentuk pola kerangka dasar, yaitu...', '["A. Gilwell Park","B. Palang tegak lurus dan silang (X)","C. Mafeking","D. Pulau Brownsea"]', 'B. Palang tegak lurus dan silang (X)'),
(20, 'Dalam Sandi Kotak 1, masing-masing ruangan kotak pada kerangka palang maksimal diisi oleh...', '["A. 7 huruf","B. 2 huruf","C. 6 huruf","D. 6 huruf"]', 'B. 2 huruf'),
(20, 'Dalam Sandi Kotak 1, huruf "B" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. 4 titik","B. 1 titik","C. 5 titik","D. 6 titik"]', 'B. 1 titik'),
(20, 'Dalam Sandi Kotak 1, huruf "A" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. Tanpa titik","B. Y","C. A","D. G"]', 'A. Tanpa titik'),
(20, 'Dalam Sandi Kotak 1, huruf "N" yang berada di kerangka silang (X) digambarkan dengan bentuk huruf V yang terbuka ke bawah, ditambah dengan...', '["A. Tanpa titik","B. U","C. G","D. Q"]', 'A. Tanpa titik'),
(20, 'Perbedaan utama antara Sandi Kotak 1 dan Sandi Kotak 2 (versi Boyman) terletak pada penempatan huruf, yaitu...', '["A. O","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. Z","D. X"]', 'B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik'),
(20, 'Dalam Sandi Kotak 2, huruf "C" ditandai dengan kotak yang sama dengan huruf A dan B, namun dibedakan menggunakan...', '["A. Z","B. R","C. Menggunakan 2 titik","D. B"]', 'C. Menggunakan 2 titik'),
(20, 'Sandi Kotak 3 memiliki bentuk dasar kerangka yang unik dan sedikit rumit, yaitu berbentuk susunan...', '["A. London","B. Belah ketupat (segi empat silang)","C. Kenya","D. Mafeking"]', 'B. Belah ketupat (segi empat silang)'),
(20, 'Sandi Rumput pada dasarnya merupakan bentuk kamuflase atau aplikasi visual murni dari...', '["A. Sandi Jam","B. Sandi Arab","C. Sandi Morse","D. Sandi Braille"]', 'C. Sandi Morse'),
(20, 'Pada Sandi Rumput, lambang titik (.) pada kode morse digambarkan dengan wujud...', '["A. 1 titik","B. Rumput pendek","C. 08.05","D. Semaphore"]', 'B. Rumput pendek'),
(20, 'Pada Sandi Rumput, lambang garis (-) pada kode morse digambarkan dengan wujud...', '["A. Rumput tinggi","B. 2","C. Semaphore","D. CENZHXN"]', 'A. Rumput tinggi'),
(20, 'Sandi yang mengubah urutan abjad sedemikian rupa sehingga abjad dibagi dua, huruf "A" dibaca "N", "B" dibaca "O", dan seterusnya, disebut...', '["A. Y","B. Sandi AN","C. M","D. V"]', 'B. Sandi AN'),
(20, 'Kata "PRAMUKA" jika dipecahkan menggunakan rumus abjad Sandi AN akan berbunyi...', '["A. CENZHXN","B. Sandi Jam","C. Merah dan Kuning","D. A-N-I-B-M-E-P"]', 'A. CENZHXN'),
(20, 'Sandi yang menukar huruf awal alfabet dengan huruf akhir (A menjadi Z, B menjadi Y, C menjadi X) disebut...', '["A. Sandi AZ / Sandi Balik Abjad","B. L","C. J","D. B"]', 'A. Sandi AZ / Sandi Balik Abjad'),
(20, 'Kata "PRAMUKA" jika dibaca ke dalam rumus Sandi AZ maka akan menjadi susunan huruf...', '["A. W","B. KIZNFPZ","C. E","D. B"]', 'B. KIZNFPZ'),
(20, 'Dalam Sandi Angka dasar, di mana A=1, B=2, dst., maka susunan kode 16-18-1-13-21-11-1 dibaca...', '["A. Sandi AND","B. 2 huruf","C. PRAMUKA","D. 1 titik"]', 'C. PRAMUKA'),
(20, 'Sandi Angka juga bisa divariasikan patokannya (misal awalan A=0). Jika A=0, maka huruf C adalah angka...', '["A. 7","B. 5","C. 2","D. 5"]', 'C. 2'),
(20, 'Sandi yang pengerjaannya menggunakan dua kata kunci yang digabungkan membentuk tabel baris dan kolom persilangan, disebut...', '["A. Sandi Siput","B. Sandi Koordinat","C. Sandi AN","D. Sandi Braille"]', 'B. Sandi Koordinat'),
(20, 'Dua buah kata yang paling sering dan umum dijadikan kata kunci dalam Sandi Koordinat Pramuka adalah...', '["A. MERAH PUTIH","B. Kuning","C. Hijau","D. Hitam"]', 'A. MERAH PUTIH'),
(20, 'Dalam Sandi Koordinat "MERAH PUTIH", huruf "M" mewakili posisi...', '["A. W","B. Baris pertama","C. T","D. B"]', 'B. Baris pertama'),
(20, 'Sandi yang memanfaatkan patokan interval selisih waktu secara berurutan sebagai pengganti abjad alfabet disebut...', '["A. Sandi AZ","B. Sandi Kimia","C. Sandi Jam","D. Sandi Angka"]', 'C. Sandi Jam'),
(20, 'Pada Sandi Jam, jika disepakati pukul 08.00 adalah huruf A, dan interval beda waktu adalah 5 menit, maka huruf B ditulis pada...', '["A. U","B. 08.05","C. Z","D. D"]', 'B. 08.05'),
(20, 'Jika pukul 07.00 = A dengan interval waktu yang sama yaitu 5 menit, jam berapakah yang akan menunjukkan huruf C?', '["A. E","B. 07.10","C. O","D. A"]', 'B. 07.10'),
(20, 'Sandi yang mengadopsi cara penulisan unsur rumus kimia, dan sebenarnya merupakan kamuflase lain dari sandi Morse, disebut...', '["A. Sandi Morse","B. Sandi Siput","C. Sandi Kimia","D. Sandi Rumput"]', 'C. Sandi Kimia'),
(20, 'Dalam ketentuan Sandi Kimia Pramuka, kelompok huruf Vokal (A, I, U, E, O) berfungsi menggantikan posisi...', '["A. Tanda Titik (.) pada Morse","B. S","C. G","D. I"]', 'A. Tanda Titik (.) pada Morse'),
(20, 'Dalam Sandi Kimia, kelompok huruf Konsonan (B, C, D, F, dst) berfungsi menggantikan posisi...', '["A. P","B. Tanda Garis (-) pada Morse","C. H","D. W"]', 'B. Tanda Garis (-) pada Morse'),
(20, 'Kode Morse ".-" (Huruf A) jika diubah ke dalam Sandi Kimia bisa ditulis menjadi wujud kombinasi Vokal-Konsonan bebas, misalnya...', '["A. OH","B. Q","C. K","D. R"]', 'A. OH'),
(20, 'Sandi kata yang cara menyembunyikannya adalah dengan menyisipkan huruf/kata "AND" di antara abjad aslinya disebut...', '["A. P","B. G","C. Sandi AND","D. D"]', 'C. Sandi AND'),
(20, 'Sandi yang bentuk aslinya menyerupai lekukan garis-garis bergelombang tak terputus, di mana lekukan kecil adalah titik dan lekukan besar/runcing adalah garis, dinamakan...', '["A. Sandi Arab","B. Sandi AZ","C. Sandi Kotak 1","D. Sandi Ular / Sandi Gergaji"]', 'D. Sandi Ular / Sandi Gergaji'),
(20, 'Sandi yang cara membacanya sama dengan metode membaca aksara Arab, yaitu dibaca terbalik dari kanan ke kiri, disebut...', '["A. Sandi Morse","B. Sandi Kimia","C. Sandi Arab","D. Sandi Semaphore"]', 'C. Sandi Arab'),
(20, 'Sebuah pesan tertulis "AKUMARP", jika dipecahkan menggunakan kaidah Sandi Arab akan dapat dibaca menjadi kata...', '["A. PRAMUKA","B. Sandi AND","C. Merah dan Kuning","D. 2"]', 'A. PRAMUKA'),
(20, 'Sandi yang cara membacanya memutar seperti cangkang kerang dari tengah ke luar atau luar ke dalam berlawanan jarum jam disebut...', '["A. Sandi Kotak 1","B. Sandi AZ","C. Sandi Siput","D. Sandi Braille"]', 'C. Sandi Siput'),
(20, 'Sandi yang menggunakan titik-titik timbul untuk membantu penyandang tunanetra membaca, yang diciptakan di Prancis adalah...', '["A. Louis Braille","B. A-N-I-B-M-E-P","C. PRAMUKA","D. CENZHXN"]', 'A. Louis Braille'),
(20, 'Susunan titik pada Sandi Braille dibentuk berdasarkan pola sebuah kotak imajiner yang berukuran...', '["A. London","B. 2 kolom dan 3 baris (total 6 titik posisi)","C. Pulau Brownsea","D. Nyeri"]', 'B. 2 kolom dan 3 baris (total 6 titik posisi)'),
(20, 'Isyarat komunikasi jarak jauh yang menggunakan peraga sepasang bendera tangan dan sering masuk dalam materi wawasan komunikasi Pramuka disebut...', '["A. 1 titik","B. OH","C. Baris pertama","D. Semaphore"]', 'D. Semaphore'),
(20, 'Ukuran standar bendera Semaphore yang biasa digunakan oleh Pramuka Penggalang adalah persegi dengan ukuran...', '["A. 45 x 45 cm","B. Rumput pendek","C. Sandi Koordinat","D. Menggunakan 2 titik"]', 'A. 45 x 45 cm'),
(20, 'Warna standar untuk bendera Semaphore agar mudah terlihat dari jarak jauh adalah perpaduan menyilang dari warna...', '["A. Coklat","B. Merah dan Kuning","C. Hijau","D. Hitam"]', 'B. Merah dan Kuning'),
(20, 'Dalam Sandi Kotak 1, huruf "Z" digambarkan menempati kerangka silang (X) pada sudut bawah dengan ditambahkan...', '["A. 4 titik","B. 6 titik","C. 1 titik","D. 2 titik"]', 'C. 1 titik'),
(20, 'Sandi yang memanipulasi abjad Morse ke dalam bentuk angka pembilang dan penyebut pecahan matematika disebut...', '["A. Sandi Pecahan / Sandi Matematika","B. Sandi AZ","C. Sandi Arab","D. Sandi Kotak 1"]', 'A. Sandi Pecahan / Sandi Matematika'),
(20, 'Pada variasi Sandi Angka, jika disepakati A=3, B=4, maka huruf D akan ditulis menggunakan angka...', '["A. 2","B. 6","C. 9","D. 7"]', 'B. 6'),
(20, 'Huruf "E" dalam kode morse hanya terdiri dari satu titik. Dalam Sandi Kimia, huruf E dapat diwakilkan cukup dengan satu huruf saja, misalnya...', '["A. Huruf Vokal, contohnya O","B. A","C. U","D. X"]', 'A. Huruf Vokal, contohnya O'),
(20, 'Huruf "T" dalam kode morse hanya terdiri dari satu garis. Dalam Sandi Kimia, huruf T dapat diwakilkan cukup dengan satu huruf, misalnya...', '["A. C","B. Huruf Konsonan, contohnya K","C. W","D. S"]', 'B. Huruf Konsonan, contohnya K'),
(20, 'Syarat utama dua buah kata yang akan dijadikan kunci dalam tabel baris/kolom Sandi Koordinat adalah gabungan katanya harus terdiri dari...', '["A. Skala","B. Protractor","C. 10 huruf tanpa ada huruf ganda yang sama","D. Indeks Kontur"]', 'C. 10 huruf tanpa ada huruf ganda yang sama'),
(20, 'Kata "Sandi" itu sendiri berarti...', '["A. Tulisan","B. Rahasia","C. Keberanian","D. Isyarat"]', 'B. Rahasia'),
(20, 'Tujuan asli dibentuknya sandi atau kriptografi pada zaman dahulu yang menginspirasi kepramukaan adalah...', '["A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. PRAMUKA","D. 10 huruf tanpa ada huruf ganda yang sama"]', 'A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh'),
(20, 'Jika Sandi Jam dimulai pukul 10.00 = A, dan beda waktu intervalnya dinaikkan menjadi 10 menit, maka pukul 10.20 menunjukkan huruf...', '["A. E","B. F","C. C","D. M"]', 'C. C'),
(20, 'Sandi rahasia unik yang menggunakan bentuk gambar tongkat orang menari dengan posisi lengan berbeda-beda (Dancing Men) terinspirasi dari novel karya...', '["A. Sir Arthur Conan Doyle (Sherlock Holmes)","B. Tanda Titik (.) pada Morse","C. Sandi Pecahan / Sandi Matematika","D. 10 huruf tanpa ada huruf ganda yang sama"]', 'A. Sir Arthur Conan Doyle (Sherlock Holmes)'),
(20, '"P-E-M-B-I-N-A" jika ditulis menggunakan rumus Sandi Arab akan menjadi susunan...', '["A. 6","B. A-N-I-B-M-E-P","C. 2","D. KIZNFPZ"]', 'B. A-N-I-B-M-E-P'),
(20, 'Salah satu Syarat Kecakapan Umum (SKU) Pramuka Penggalang mewajibkan anggotanya untuk dapat memahami, membaca, dan mengirimkan pesan isyarat dasar yaitu...', '["A. Merah dan Kuning","B. 45 x 45 cm","C. Morse dan Semaphore","D. Semaphore"]', 'C. Morse dan Semaphore'),

-- ==========================================
-- BAB 24: P3K & Kesehatan
-- ==========================================
(24, 'Singkatan dari P3K adalah...', '["A. Disentri","B. Pertolongan Pertama Pada Kecelakaan","C. Terkilir","D. Patah Tulang"]', 'B. Pertolongan Pertama Pada Kecelakaan'),
(24, 'Tujuan utama dari pemberian P3K adalah...', '["A. Patah Tulang","B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","C. Luka Bakar","D. Demam Berdarah"]', 'B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk'),
(24, 'Langkah pertama yang harus dilakukan saat menemukan korban kecelakaan adalah...', '["A. Tenang, Cepat, Tepat, dan Tidak Panik","B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","C. 50-100 cm (agar tidak dibongkar hewan)","D. Balut tekan (tekan langsung di atas luka)"]', 'B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)'),
(24, 'Pembalut segitiga yang sangat sering digunakan dalam P3K Pramuka disebut...', '["A. Disentri","B. Pingsan","C. Mitela","D. Diare"]', 'C. Mitela'),
(24, 'Alat keras/kaku yang digunakan untuk menahan tulang yang patah agar tidak bergerak disebut...', '["A. Matras","B. Bidai / Spalk","C. Tenda Prisma","D. Sleeping Bag (Kantong Tidur)"]', 'B. Bidai / Spalk'),
(24, 'Pertolongan pertama pada korban mimisan yang benar adalah...', '["A. Tenang, Cepat, Tepat, dan Tidak Panik","B. Menundukkan kepala ke depan dan menjepit cuping hidung","C. Nadi cepat dan lemah, kulit pucat, keringat dingin","D. 50-100 cm (agar tidak dibongkar hewan)"]', 'B. Menundukkan kepala ke depan dan menjepit cuping hidung'),
(24, 'Pendarahan arteri ditandai dengan ciri-ciri...', '["A. Abu-abu","B. Darah memancar seirama denyut jantung dan berwarna merah terang","C. Kuning","D. Biru"]', 'B. Darah memancar seirama denyut jantung dan berwarna merah terang'),
(24, 'Cara menghentikan pendarahan luar yang paling efektif adalah dengan teknik...', '["A. Balut tekan (tekan langsung di atas luka)","B. Barat","C. Utara","D. Timur Laut"]', 'A. Balut tekan (tekan langsung di atas luka)'),
(24, 'Simpul yang digunakan untuk mengakhiri balutan mitela agar mudah dilepas adalah...', '["A. Simpul Tiang (Bowline)","B. Simpul Mati","C. Ikatan Silang","D. Simpul Mati (Reef Knot)"]', 'B. Simpul Mati'),
(24, 'Kondisi penurunan suhu tubuh secara drastis akibat cuaca dingin di gunung disebut...', '["A. Simpul Mati","B. Hipotermia","C. 30 : 2","D. Bidai / Spalk"]', 'B. Hipotermia'),
(24, 'Pertolongan pertama pada luka bakar ringan (derajat 1) adalah...', '["A. Terkilir","B. Dialiri air bersih mengalir selama 10-15 menit","C. Disentri","D. Diare"]', 'B. Dialiri air bersih mengalir selama 10-15 menit'),
(24, 'Alat untuk mengangkut korban kecelakaan secara darurat yang dibuat dari dua tongkat dan tali disebut...', '["A. Disentri","B. Tandu Darurat (Dragbar)","C. Hipotermia","D. Pingsan"]', 'B. Tandu Darurat (Dragbar)'),
(24, 'Jumlah ikatan minimal pada pemasangan bidai untuk patah tulang tungkai bawah adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Simpul Delapan","D. Minimal melewati dua sendi"]', 'D. Minimal melewati dua sendi'),
(24, 'Korban pingsan sebaiknya diposisikan telentang dengan posisi kaki...', '["A. Rest, Ice, Compression, Elevation","B. Gigitan hewan (anjing/kucing) untuk cegah rabies","C. Lebih tinggi dari kepala (Elevasi)","D. Menyelamatkan nyawa dan mencegah kondisi korban memburuk"]', 'C. Lebih tinggi dari kepala (Elevasi)'),
(24, 'Isi kotak P3K yang berfungsi untuk membersihkan luka dari kuman adalah...', '["A. Hipotermia","B. Antiseptik (Betadine/Rivanol)","C. Patah Tulang","D. Disentri"]', 'B. Antiseptik (Betadine/Rivanol)'),
(24, 'Penyakit yang disebabkan oleh gigitan nyamuk Aedes Aegypti adalah...', '["A. Diare","B. Demam Berdarah (Dengue)","C. Patah Tulang","D. Pendarahan"]', 'B. Demam Berdarah (Dengue)'),
(24, 'Cara menangani kaki yang terkilir (kram/keseleo) dengan metode RICE, singkatan dari...', '["A. Simpul Mati","B. Rest, Ice, Compression, Elevation","C. Lebih tinggi dari kepala (Elevasi)","D. Pinset dan air bersih"]', 'B. Rest, Ice, Compression, Elevation'),
(24, 'Pertolongan pertama jika seseorang tersedak makanan dan sulit bernapas adalah dengan...', '["A. Susu / Air kelapa","B. Manuver Heimlich (hentakan pada perut)","C. Mencegah kulit korban terluka saat menggunting perban","D. Air bersih / Boorwater"]', 'B. Manuver Heimlich (hentakan pada perut)'),
(24, 'Obat yang digunakan untuk mengurangi rasa sakit kepala atau demam ringan adalah...', '["A. Antasida","B. Parasetamol","C. Segitiga terbuka","D. Tetanus"]', 'B. Parasetamol'),
(24, 'Untuk mengganti cairan tubuh yang hilang akibat diare, sebaiknya diberikan...', '["A. Segitiga terbuka","B. Oralit","C. Termometer","D. 36-37 derajat"]', 'B. Oralit'),
(24, 'Pembalutan pada luka di kepala biasanya menggunakan mitela yang dilipat menjadi bentuk...', '["A. Terkilir","B. Segitiga terbuka","C. Diare","D. Disentri"]', 'B. Segitiga terbuka'),
(24, 'Luka yang disebabkan oleh benda tumpul dan menyebabkan memar kebiruan disebut luka...', '["A. Terkilir","B. Luka Memar (Contusio)","C. Demam Berdarah","D. Luka Bakar"]', 'B. Luka Memar (Contusio)'),
(24, 'Tindakan RJP (Resusitasi Jantung Paru) dilakukan pada korban yang...', '["A. Minimal melewati dua sendi","B. Henti napas dan henti jantung","C. 30 : 2","D. Minyak Kayu Putih / Kaladin"]', 'B. Henti napas dan henti jantung'),
(24, 'Pada saat memindahkan korban dengan tandu, posisi kepala korban sebaiknya berada di...', '["A. Tenang, Cepat, Tepat, dan Tidak Panik","B. Belakang (berlawanan arah jalan)","C. Putih dengan tanda palang merah/hijau","D. Terkilir / Cedera sendi"]', 'B. Belakang (berlawanan arah jalan)'),
(24, 'Warna kotak P3K standar biasanya adalah...', '["A. Biru","B. Putih dengan tanda palang merah/hijau","C. Hitam","D. Ungu"]', 'B. Putih dengan tanda palang merah/hijau'),
(24, 'Pertolongan pertama pada gigitan ular yang paling tepat adalah...', '["A. Menutup luka agar tidak infeksi dan menyerap darah","B. Nadi cepat dan lemah, kulit pucat, keringat dingin","C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS","D. Menundukkan kepala ke depan dan menjepit cuping hidung"]', 'C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS'),
(24, 'Pembalut elastis (Elastic Bandage) sangat baik digunakan untuk menangani...', '["A. Antiseptik (Betadine/Rivanol)","B. Terkilir / Cedera sendi","C. Demam Berdarah (Dengue)","D. Susu / Air kelapa"]', 'B. Terkilir / Cedera sendi'),
(24, 'Penyakit yang sering muncul di perkemahan akibat sanitasi buruk dan air kotor adalah...', '["A. Pingsan","B. Diare","C. Terkilir","D. Disentri"]', 'B. Diare'),
(24, 'Kasa steril diletakkan langsung di atas luka bertujuan untuk...', '["A. Disentri","B. Menutup luka agar tidak infeksi dan menyerap darah","C. Hipotermia","D. Luka Bakar"]', 'B. Menutup luka agar tidak infeksi dan menyerap darah'),
(24, 'Berapa jumlah penolong yang ideal untuk mengangkat tandu darurat?', '["A. Terkilir","B. 2-4 orang","C. Hipotermia","D. Pingsan"]', 'B. 2-4 orang'),
(24, 'Alat untuk mengukur suhu tubuh manusia disebut...', '["A. 16 - 20 tahun","B. Termometer","C. 17 - 25 tahun","D. 11 - 15 tahun"]', 'B. Termometer'),
(24, 'Suhu tubuh normal manusia berkisar antara...', '["A. 21 - 25 tahun","B. 36-37 derajat","C. 14 - 18 tahun","D. 7 - 10 tahun"]', 'B. 36-37 derajat'),
(24, 'Tindakan yang harus dihindari saat menolong korban patah tulang adalah...', '["A. Susu / Air kelapa","B. Mencoba meluruskan posisi tulang secara paksa","C. Air bersih / Boorwater","D. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)"]', 'B. Mencoba meluruskan posisi tulang secara paksa'),
(24, 'Mencuci tangan sebelum makan dan setelah beraktivitas merupakan contoh...', '["A. Mencoba meluruskan posisi tulang secara paksa","B. Perilaku Hidup Bersih dan Sehat (PHBS)","C. Mencegah kulit korban terluka saat menggunting perban","D. Manuver Heimlich (hentakan pada perut)"]', 'B. Perilaku Hidup Bersih dan Sehat (PHBS)'),
(24, 'Cairan yang digunakan untuk mencuci mata jika kemasukan debu adalah...', '["A. Tandu Darurat (Dragbar)","B. Air bersih / Boorwater","C. Segitiga terbuka","D. Lengan / Bahu"]', 'B. Air bersih / Boorwater'),
(24, 'Pembalut Mitela dilipat menjadi "Gendongan" berfungsi untuk menyangga cedera pada...', '["A. Termometer","B. Lengan / Bahu","C. Tandu Darurat (Dragbar)","D. Demam Berdarah (Dengue)"]', 'B. Lengan / Bahu'),
(24, 'Tanda-tanda seseorang mengalami syok (shock) adalah...', '["A. Menutup luka agar tidak infeksi dan menyerap darah","B. Nadi cepat dan lemah, kulit pucat, keringat dingin","C. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","D. Dialiri air bersih mengalir selama 10-15 menit"]', 'B. Nadi cepat dan lemah, kulit pucat, keringat dingin'),
(24, 'Zat racun dalam makanan dapat dinetralkan sementara (sebelum ke dokter) dengan meminum...', '["A. Susu / Air kelapa","B. 2-4 orang","C. Manuver Heimlich (hentakan pada perut)","D. Belakang (berlawanan arah jalan)"]', 'A. Susu / Air kelapa'),
(24, 'Obat luar yang digunakan untuk meredakan gatal akibat gigitan serangga adalah...', '["A. Manuver Heimlich (hentakan pada perut)","B. Minyak Kayu Putih / Kaladin","C. Putih dengan tanda palang merah/hijau","D. Dialiri air bersih mengalir selama 10-15 menit"]', 'B. Minyak Kayu Putih / Kaladin'),
(24, 'Luka tusuk akibat paku berkarat sangat berisiko menyebabkan penyakit...', '["A. Patah Tulang","B. Tetanus","C. Terkilir","D. Luka Bakar"]', 'B. Tetanus'),
(24, 'Pada RJP (CPR), rasio kompresi dada dan napas buatan untuk satu penolong adalah...', '["A. Bidai / Spalk","B. 30 : 2","C. Diare","D. 2-4 orang"]', 'B. 30 : 2'),
(24, 'Pembalutan luka di lutut yang sedang ditekuk paling baik menggunakan teknik...', '["A. Balutan angka delapan","B. Disentri","C. Terkilir","D. Pingsan"]', 'A. Balutan angka delapan'),
(24, 'Bagian dari tas P3K yang digunakan untuk memotong perban atau pakaian korban adalah...', '["A. Demam Berdarah","B. Gunting","C. Terkilir","D. Disentri"]', 'B. Gunting'),
(24, 'Untuk membersihkan luka yang kotor dari kerikil atau pasir digunakan...', '["A. Diare","B. Pinset dan air bersih","C. Pendarahan","D. Disentri"]', 'B. Pinset dan air bersih'),
(24, 'Apa yang harus dilakukan jika korban tersambar petir?', '["A. Menutup luka agar tidak infeksi dan menyerap darah","B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS","C. Balut tekan (tekan langsung di atas luka)","D. Susu / Air kelapa"]', 'B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS'),
(24, 'Gunting yang bagian ujungnya tumpul (Gunting Verban) bertujuan untuk...', '["A. Balut tekan (tekan langsung di atas luka)","B. Mencegah kulit korban terluka saat menggunting perban","C. Tenang, Cepat, Tepat, dan Tidak Panik","D. Dialiri air bersih mengalir selama 10-15 menit"]', 'B. Mencegah kulit korban terluka saat menggunting perban'),
(24, 'Kesehatan lingkungan perkemahan dijaga dengan cara membuat lubang sampah sedalam...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. 50-100 cm (agar tidak dibongkar hewan)","C. Minimal melewati dua sendi","D. Perilaku Hidup Bersih dan Sehat (PHBS)"]', 'B. 50-100 cm (agar tidak dibongkar hewan)'),
(24, 'Obat yang digunakan untuk menolong sakit perut akibat maag adalah...', '["A. Segitiga terbuka","B. Antasida","C. 2-4 orang","D. Hipotermia"]', 'B. Antasida'),
(24, 'Mencuci luka dengan air sabun sangat disarankan khusus untuk luka akibat...', '["A. Pingsan","B. Gigitan hewan (anjing/kucing) untuk cegah rabies","C. Hipotermia","D. Luka Bakar"]', 'B. Gigitan hewan (anjing/kucing) untuk cegah rabies'),
(24, 'Prinsip utama penolong P3K adalah...', '["A. Diare","B. Tenang, Cepat, Tepat, dan Tidak Panik","C. Demam Berdarah","D. Terkilir"]', 'B. Tenang, Cepat, Tepat, dan Tidak Panik'),

-- ==========================================
-- BAB 99: Tambahan / Campuran
-- ==========================================
(99, 'Gerakan kepanduan di Indonesia resmi diakui dan menjadi anggota WOSM (World Organization of the Scout Movement) pada tahun...', '["A. 1951","B. 1953","C. 1954","D. 1955"]', 'B. 1953'),
(99, 'Sifat kepramukaan yang berarti penyelenggaraannya disesuaikan dengan keadaan, kebutuhan, dan kepentingan masyarakat di negaranya adalah sifat...', '["A. Sandi","B. Nasional","C. Kejayaan","D. Kekuatan"]', 'B. Nasional'),
(99, 'Semboyan Sistem Among "Ing Madyo Mangun Karso" memiliki arti seorang Pembina harus mampu...', '["A. Kesucian","B. Di tengah membangun kemauan/semangat","C. Pesan","D. Isyarat"]', 'B. Di tengah membangun kemauan/semangat'),
(99, 'Tanda Kecakapan Khusus (TKK) tingkat tertinggi yang bentuknya segilima beraturan adalah tingkat...', '["A. Bantara, Laksana","B. Purwa, Madya, Utama","C. Utama","D. Mula, Bantu, Tata"]', 'C. Utama'),
(99, 'Undang-Undang Republik Indonesia yang secara khusus mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. Simpul Tali Tenda (Taut-line Hitch)","B. UU No. 12 Tahun 2010","C. 1 : 3","D. Rest, Ice, Compression, Elevation"]', 'B. UU No. 12 Tahun 2010'),
(99, 'Bapak Pandu Dunia (Chief Scout of the World) dan Bapak Pramuka Indonesia secara berurutan adalah...', '["A. Agnes Baden-Powell","B. Andri Bob Sunardi","C. Baden Powell dan Sri Sultan Hamengkubuwono IX","D. Rudyard Kipling"]', 'C. Baden Powell dan Sri Sultan Hamengkubuwono IX'),
(99, 'Penggolongan usia Pramuka Penegak yang tepat adalah...', '["A. 14 - 18 tahun","B. 21 - 25 tahun","C. 16 - 20 tahun","D. 11 - 15 tahun"]', 'C. 16 - 20 tahun'),
(99, 'Meskipun lekat dengan dunia militer, ayah dari Baden-Powell sejatinya adalah seorang...', '["A. Baden Powell dan Sri Sultan Hamengkubuwono IX","B. Guru Besar Geometri di Universitas Oxford","C. Simpul Anyam (Sheet Bend)","D. Rest, Ice, Compression, Elevation"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(99, 'Suku-suku di Afrika memberikan julukan "Impeesa" kepada Baden-Powell, yang memiliki makna filosofis...', '["A. Terkilir","B. Luka Bakar","C. Serigala yang tidak pernah tidur","D. Diare"]', 'C. Serigala yang tidak pernah tidur'),
(99, 'Buku mahakarya Baden-Powell yang ditujukan khusus untuk golongan pemuda (Rover Scout) pada tahun 1922 berjudul...', '["A. Scouting for Boys","B. The Jungle Book","C. Boyman","D. Rovering to Success"]', 'D. Rovering to Success'),
(99, 'Kalung manik-manik kayu (Wood Badge) yang dikalungkan pada Pembina Pramuka lulusan kursus lanjutan berasal dari kalung pimpinan suku Afrika bernama...', '["A. H. Mutahar","B. Lord Robert Baden Powell","C. Dinizulu","D. Samuel F.B. Morse"]', 'C. Dinizulu'),
(99, 'Pada batu nisan makam Baden-Powell di Nyeri, Kenya, terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti rahasia...', '["A. Kejayaan","B. Saya telah pulang","C. Kesucian","D. Sandi"]', 'B. Saya telah pulang'),
(99, 'Pasukan kavaleri pertama yang ditempati Baden-Powell saat bertugas ke India dengan pangkat Pembantu Letnan adalah...', '["A. Pulau Brownsea","B. Gilwell Park","C. 13th Hussars","D. Olympia Hall"]', 'C. 13th Hussars'),
(99, 'Buku Scouting for Boys secara struktural dibagi ke dalam 26 bab khusus yang oleh Baden-Powell disebut dengan istilah...', '["A. Boyman","B. Cerita Api Unggun (Campfire Yarns)","C. The Jungle Book","D. Aids to Scouting"]', 'B. Cerita Api Unggun (Campfire Yarns)'),
(99, 'Simpul yang paling tepat digunakan untuk menyambung dua utas tali yang ukurannya TIDAK SAMA besar dan dalam keadaan kering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Simpul Mati (Reef Knot)","D. Simpul Tiang (Bowline)"]', 'A. Simpul Anyam (Sheet Bend)'),
(99, 'Prinsip konservasi dalam Cerita Api Unggun ke-15 melarang pandu membunuh binatang apa pun, KECUALI...', '["A. Ikhlas Bakti Bina Bangsa","B. Be Prepared (Selalu Siap)","C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","D. Satyaku Kudarmakan, Darmaku Kubaktikan"]', 'C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup'),
(99, 'Tokoh orang suci pelindung Inggris yang dijadikan simbol ksatria kaum pandu di seluruh dunia (diperingati setiap 23 April) karena keberaniannya menumpas naga adalah...', '["A. Mayor Kenneth McLaren","B. Santo George (St. George)","C. Soenardjo Atmodipuro","D. Lord Robert Baden Powell"]', 'B. Santo George (St. George)'),
(99, 'Tindakan yang Paling Tepat jika pakaian yang dikenakan tiba-tiba tersambar api menurut panduan P3K Scouting for Boys adalah...', '["A. Demam Berdarah","B. Pendarahan","C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","D. Terkilir"]', 'C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal'),
(99, 'Inspirasi utama Baden-Powell tentang pentingnya pemuda bermula dari pasukan anak-anak saat pengepungan kota Mafeking yang dipimpin oleh...', '["A. Pulau Brownsea","B. Lord Edward Cecil","C. Mafeking","D. Nyeri"]', 'B. Lord Edward Cecil'),
(99, 'Mendirikan tenda di dasar cekungan (lembah sempit kering) sangat dilarang oleh aturan perkemahan tingkat lanjut karena risiko...', '["A. Ransel (Carrier / Backpack)","B. Flysheet","C. Terjebak banjir bandang jika hujan lebat turun di hulu","D. Nesting"]', 'C. Terjebak banjir bandang jika hujan lebat turun di hulu'),
(99, 'Agar pasak tenda menancap kuat dan tidak mudah tercabut oleh angin, kemiringan pasak ke dalam tanah harus membentuk sudut...', '["A. Ransel (Carrier / Backpack)","B. 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Sleeping Bag (Kantong Tidur)","D. Flysheet"]', 'B. 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(99, 'Celana berbahan Jeans/Denim dilarang keras dipakai untuk pendakian dan kemah alam bebas karena alasan medis, yaitu...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit"]', 'B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia'),
(99, 'Penerapan prinsip "Pack it in, Pack it out" dalam manajemen sampah perkemahan berarti...', '["A. Keberanian","B. Pesan","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Tulisan"]', 'C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya'),
(99, 'Simpul yang paling praktis untuk menautkan tali tenda pada pasak karena bisa ditarik ulur (dikencangkan/dikendurkan) tanpa melepas simpul adalah...', '["A. Simpul Pangkal (Clove Hitch)","B. Simpul Tali Tenda (Taut-line Hitch)","C. Simpul Delapan","D. Simpul Tiang (Bowline)"]', 'B. Simpul Tali Tenda (Taut-line Hitch)'),
(99, 'Jarak minimal yang direkomendasikan untuk membangun MCK (Mandi Cuci Kakus) darurat dari sumber mata air agar tidak mencemari lingkungan adalah...', '["A. Terkilir","B. Disentri","C. 15 - 20 meter","D. Pingsan"]', 'C. 15 - 20 meter'),
(99, 'Menurut standar telegrafi internasional, perbandingan durasi waktu antara ketukan "titik" (dot) dan "garis" (dash) dalam sandi Morse adalah...', '["A. Curvimeter","B. 1 : 3","C. Baris M, Kolom P","D. Rest, Ice, Compression, Elevation"]', 'B. 1 : 3'),
(99, 'Isyarat prosedural (Prosign) standar internasional untuk "Attention" atau tanda memulai pesan Morse yang sah adalah...', '["A. -.-","B. ...","C. -.-.-","D. ..-"]', 'C. -.-.-'),
(99, 'Jika huruf "O" adalah (---) dan "S" adalah (...), maka huruf "C" dalam kode morse adalah...', '["A. -.-.","B. I","C. Y","D. P"]', 'A. -.-.'),
(99, 'Jika memecahkan kata menggunakan "Sandi AND", hal pertama yang harus dilakukan adalah...', '["A. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. UU No. 12 Tahun 2010","D. 45-60 derajat berlawanan dengan arah tarikan tali tenda"]', 'B. Menghapus semua rangkaian huruf A-N-D yang berdekatan'),
(99, 'Huruf Q dan P dalam kode morse memiliki kombinasi garis yang mengecoh. Kombinasi yang benar secara berurutan untuk Q dan P adalah...', '["A. --.- dan .--.","B. Q","C. A","D. M"]', 'A. --.- dan .--.'),
(99, 'Isyarat bahwa pesan telah selesai seluruhnya (End of Message) dikirimkan dengan sandi...', '["A. Sandi Jam","B. AR (.-.-.)","C. --.- dan .--.","D. 16 - 20 tahun"]', 'B. AR (.-.-.)'),
(99, 'Jika membaca peta topografi berskala 1:50.000 dan jarak dua titik di peta adalah 4 cm, maka jarak sebenarnya di medan adalah...', '["A. 3 kilometer","B. 2 kilometer","C. 7 kilometer","D. 7 kilometer"]', 'B. 2 kilometer'),
(99, 'Garis kontur yang tergambar menjorok ke arah tempat yang lebih tinggi (membentuk huruf V terbalik) secara topografi merupakan...', '["A. V","B. Lembah atau aliran air","C. N","D. D"]', 'B. Lembah atau aliran air'),
(99, 'Aturan baku "Golden Rule" dalam membaca koordinat Grid (UTM) 6 angka pada peta topografi adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. UTM","C. Intersection","D. Deklinasi"]', 'A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)'),
(99, 'Perbedaan sudut putar yang ditunjukkan antara Utara Magnetis di jarum kompas dan Utara Peta (Grid) pada selembar peta disebut...', '["A. Barat Daya","B. Barat Laut","C. Deklinasi Magnetis","D. Timur Laut"]', 'C. Deklinasi Magnetis'),
(99, 'Alat mekanis dengan roda gigi kecil yang dijalankan menyusuri kelokan sungai di peta untuk menghitung jarak rute melengkung disebut...', '["A. UTM","B. Protractor","C. Garis Kontur","D. Curvimeter"]', 'D. Curvimeter'),
(99, 'Metode navigasi siang hari tanpa kompas menggunakan bayangan tongkat tegak lurus yang memanfaatkan pergerakan semu matahari disebut...', '["A. Sandi Ular / Sandi Gergaji","B. Sundial (Metode Bayangan Matahari)","C. Di tengah membangun kemauan/semangat","D. Deklinasi Magnetis"]', 'B. Sundial (Metode Bayangan Matahari)'),
(99, 'Dalam pemecahan Sandi Kotak 2, satu kotak kerangka silang dihuni oleh 3 huruf. Jika terdapat 2 titik di atas kerangka tersebut, maka itu menunjukkan huruf...', '["A. D","B. M","C. Ketiga","D. L"]', 'C. Ketiga'),
(99, 'Sandi Kimia mengonversi kode Morse ke huruf. Jika kode aslinya adalah "H2O" (H=konsonan, O=vokal), maka morse yang terbentuk adalah...', '["A. R","B. L","C. --.","D. V"]', 'C. --.'),
(99, 'Sandi yang menggunakan patokan waktu dengan selisih yang konstan (misal pukul 08.00 = A, 08.05 = B, 08.10 = C) disebut...', '["A. Sandi AN","B. Sandi Kimia","C. Sandi Jam","D. Sandi Ular"]', 'C. Sandi Jam'),
(99, 'Sandi AZ menukar huruf awal dengan huruf akhir alfabet. Jika sandinya berbunyi "K", maka huruf aslinya adalah...', '["A. I","B. P","C. S","D. Y"]', 'B. P'),
(99, 'Sandi yang bentuk fisiknya memanjang menyerupai gerigi atau gelombang naik turun tanpa spasi putus disebut...', '["A. Sandi AZ","B. Sandi Kotak 1","C. Sandi Ular / Sandi Gergaji","D. Sandi Braille"]', 'C. Sandi Ular / Sandi Gergaji'),
(99, 'Dalam Sandi Koordinat tabel 5x5 dengan kata kunci "MERAH PUTIH", huruf A terletak pada titik temu kordinat...', '["A. Baris M, Kolom P","B. A","C. E","D. O"]', 'A. Baris M, Kolom P'),
(99, 'Tindakan Pertolongan Pertama yang BENAR pada korban kecelakaan yang mimisan (hidung berdarah) adalah...', '["A. Utara","B. Tenggara","C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","D. Timur"]', 'C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit'),
(99, 'Rasio kompresi dada (pijat jantung) dan bantuan napas buatan pada RJP (Resusitasi Jantung Paru) untuk 1 orang penolong menurut standar medis terbaru adalah...', '["A. Guru Besar Geometri di Universitas Oxford","B. 30 kompresi : 2 napas","C. Sandi Ular / Sandi Gergaji","D. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak"]', 'B. 30 kompresi : 2 napas'),
(99, 'Penanganan keseleo (terkilir) di lapangan paling efektif menggunakan metode RICE, yang merupakan singkatan dari...', '["A. Rest, Ice, Compression, Elevation","B. 13th Hussars","C. 2 kilometer","D. Saya telah pulang"]', 'A. Rest, Ice, Compression, Elevation'),
(99, 'Alasan dilarangnya mengoleskan pasta gigi, mentega, atau kecap pada luka bakar melepuh adalah...', '["A. Luka Bakar","B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","C. Terkilir","D. Disentri"]', 'B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat'),
(99, 'Jika digigit ular berbisa di tengah hutan, penanganan paling krusial sebelum di bawa ke RS adalah...', '["A. 14 - 18 tahun","B. 11 - 15 tahun","C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening","D. 21 - 25 tahun"]', 'C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening'),
(99, 'Luka tusuk yang diakibatkan oleh benda kotor berkarat (seperti paku) sangat berisiko fatal jika tidak dicuci bersih karena membawa bakteri penyebab...', '["A. Pingsan","B. Terkilir","C. Tetanus","D. Pendarahan"]', 'C. Tetanus'),
(99, 'Pembalut elastis berwarna coklat (Elastic Bandage) sangat direkomendasikan berada di dalam kotak P3K Pramuka karena berfungsi spesifik untuk...', '["A. Merah","B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","C. Abu-abu","D. Hitam"]', 'B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak')